  'Human Resource Management in Hospitality',
  'This course equips future hospitality managers to design and operate fair, lawful, inclusive, safe, and high-performing employment systems. Students forecast labor, analyze and design jobs, recruit and select talent, onboard and develop employees, create engagement and voice, manage performance, design rewards and schedules, administer employee and labor relations, protect safety and well-being, strengthen retention and succession, and use HR technology and people analytics responsibly. Applied cases culminate in an integrated people strategy and HR policy implementation plan.',
  $hrhjjson${"slug": "human-resource-management-in-hospitality", "title": "Human Resource Management in Hospitality", "description": "This course equips future hospitality managers to design and operate fair, lawful, inclusive, safe, and high-performing employment systems. Students forecast labor, analyze and design jobs, recruit and select talent, onboard and develop employees, create engagement and voice, manage performance, design rewards and schedules, administer employee and labor relations, protect safety and well-being, strengthen retention and succession, and use HR technology and people analytics responsibly. Applied cases culminate in an integrated people strategy and HR policy implementation plan.", "topics": [{"id": "b261e9fa-664b-4e42-933a-acc3cc893a36", "type": "topic", "title": "Strategic Human Resource Management and the Hospitality Employment System", "description": "Human resource management links the guest promise, operating model, workforce experience, legal duties, and business results. This section establishes HR as a strategic and ethical management system—not a collection of transactions.", "children": [{"id": "fd7921a6-6cde-45a5-922b-9541dc5b6583", "type": "subtopic", "title": "HR strategy and the service-profit logic", "children": [{"id": "3b29c145-ef9b-4b37-8771-c12592c62edc", "type": "concept", "title": "Business and brand strategy; guest promise; service concept; operating model; people implications"}, {"id": "7a66cce4-8c8d-4686-8c26-41daafbe31b1", "type": "concept", "title": "Employee experience, service climate, discretionary effort, service quality, guest loyalty, productivity, and value"}, {"id": "36ce906c-cc6e-4719-89e8-e6966e8406eb", "type": "concept", "title": "Strategic alignment, horizontal consistency among HR practices, tradeoffs, and unintended consequences"}], "description": "Students learn why staffing quality, employee capability, service climate, guest outcomes, and financial performance must be managed as one chain."}, {"id": "e0277bf8-9f8a-4429-9f3f-53d75e8fb002", "type": "subtopic", "title": "HR roles, operating model, and line-manager accountability", "children": [{"id": "561ada77-139d-476f-8fdd-b32cc4644929", "type": "concept", "title": "HR business partner, center of expertise, shared service, property HR, outsourced provider, and line manager roles"}, {"id": "a1ffd028-fc88-465e-9ce1-0cc63cfcfbb6", "type": "concept", "title": "Decision rights, service levels, escalation, documentation, confidentiality, and manager capability"}, {"id": "b199c1cc-5f6d-42ec-89c2-2c214dfec201", "type": "concept", "title": "Employee lifecycle: plan, attract, select, onboard, develop, deploy, reward, engage, retain, transition, and learn"}], "description": "This subtopic clarifies who owns workforce decisions across corporate, brand, regional, property, department, and shift levels."}, {"id": "5cb27bac-f486-4b6c-8d22-20cbfac185f4", "type": "subtopic", "title": "Ethical practice and stakeholder responsibilities", "children": [{"id": "ea6675b8-c95b-40c0-9f33-be870e7c0f2c", "type": "concept", "title": "Ethical reasoning, conflicts of interest, power asymmetry, consistency, procedural justice, and due process"}, {"id": "8808af37-71d1-4eee-9f1f-ef2f00744d8e", "type": "concept", "title": "Guests, employees, applicants, owners, managers, unions, contractors, communities, and regulators"}, {"id": "1961d9b0-b1d0-4b56-a01d-0a772e7119a2", "type": "concept", "title": "Speak-up channels, nonretaliation, records, conflicts, safeguards, remedies, and accountable leadership"}], "description": "Students practice balancing organizational goals with dignity, fairness, voice, safety, privacy, and community impact."}]}, {"id": "adddffcd-f5f3-42ec-a10b-71ea7eabce9a", "type": "topic", "title": "Service Workforce Planning, Job Analysis, and Work Design", "description": "Hospitality demand is variable, perishable, and labor intensive. Workforce planning converts forecasts and service standards into the right roles, skills, headcount, hours, and contingencies without treating people as interchangeable units.", "children": [{"id": "ae868140-a503-4810-ab59-1ca3bac00254", "type": "subtopic", "title": "Demand, labor, and skills forecasting", "children": [{"id": "cba74c0c-498e-46e5-bdc2-a2a5748d0f48", "type": "concept", "title": "Demand drivers, workload standards, labor hours per occupied room/cover, productivity, utilization, and service risk"}, {"id": "38cb05e2-40b9-415a-9366-186c07691722", "type": "concept", "title": "Headcount, FTE, hours, skill mix, fixed/variable labor, overtime, agency labor, and labor-cost percentage"}, {"id": "30c63f69-ca8a-4c14-bcca-d033659bb1bd", "type": "concept", "title": "Base/upside/downside scenarios, vacancy and absence buffers, peak planning, contingencies, and forecast error"}], "description": "Students translate occupancy, covers, events, seasonality, service level, and productivity assumptions into staffing requirements."}, {"id": "de2c4675-0a8d-40d8-b33c-1a7883b896e6", "type": "subtopic", "title": "Job analysis and competency modeling", "children": [{"id": "ea35d6fb-9d9d-4c6a-afbe-32df94414ff4", "type": "concept", "title": "Observation, interviews, diaries, critical incidents, workflow data, O*NET, and subject-matter validation"}, {"id": "b7975e9e-5752-493e-8457-02e2a6aeacc0", "type": "concept", "title": "Job description, person specification, essential versus marginal functions, physical/cognitive demands, and working conditions"}, {"id": "b775c244-ac18-4041-aa20-3d74e7703eee", "type": "concept", "title": "Technical, service, leadership, safety, digital, language, intercultural, and behavioral competencies"}], "description": "A defensible job system begins with evidence about work, essential functions, knowledge, skills, abilities, behaviors, and context."}, {"id": "c19038c1-8f17-4bcb-a2c9-ffd5ceba74aa", "type": "subtopic", "title": "Work design and employment architecture", "children": [{"id": "f81686bf-a60e-408d-b9a5-885de1b9c057", "type": "concept", "title": "Task variety, autonomy, feedback, interdependence, emotional labor, role clarity, workload, and ergonomics"}, {"id": "a229253f-ebcb-4d5e-80a6-7c8bc897561f", "type": "concept", "title": "Full-time, part-time, seasonal, on-call, temporary, contractor, franchise, and multi-property arrangements"}, {"id": "414420a9-bc35-4039-9d5b-c93e4ac8a598", "type": "concept", "title": "Cross-training, teams, job rotation, enrichment, scheduling flexibility, remote-capable work, and automation impacts"}], "description": "Students design work that supports service, safety, inclusion, learning, flexibility, and sustainable performance."}]}, {"id": "7d0abc36-3976-4ff0-bc3d-9a432b607129", "type": "topic", "title": "Employer Brand, Talent Sourcing, and Recruitment", "description": "Recruitment is a two-way market process: the organization seeks qualified talent while applicants judge credibility, fairness, work conditions, growth, and belonging. Hospitality employers must create realistic promises they can keep.", "children": [{"id": "2b00d154-73e8-48d7-86fa-f0fa6d09ed7f", "type": "subtopic", "title": "Employer value proposition and labor-market intelligence", "children": [{"id": "400701a9-ac29-40c0-b204-08923132ab7b", "type": "concept", "title": "Target talent segments, candidate personas, employee listening, competitor benchmarks, and local labor supply"}, {"id": "0fc77e1d-44b4-4c7b-ae61-21ddef3fbce3", "type": "concept", "title": "Pay, schedules, benefits, purpose, culture, manager quality, learning, mobility, well-being, and recognition"}, {"id": "2f83d2c9-93a7-4df1-94c4-6e81a279d38e", "type": "concept", "title": "Brand authenticity, employee reviews, reputation risk, realistic job previews, and promise-delivery gaps"}], "description": "Students define why target candidates would join, stay, and contribute—and test that promise against actual work."}, {"id": "9d163ba1-245a-4733-bf75-fd89416b795a", "type": "subtopic", "title": "Sourcing strategy and partnerships", "children": [{"id": "8982b299-e846-4577-ae0b-683e26f4a40e", "type": "concept", "title": "Internal mobility, referrals, schools, community groups, workforce agencies, associations, events, and digital channels"}, {"id": "d5daea6b-a64c-4b53-8408-849d9846b3d9", "type": "concept", "title": "Passive and active candidates, alumni, returners, seasonal pools, internships, apprenticeships, and international talent"}, {"id": "bbb5214e-655c-4a6d-8f8f-f0e645db2591", "type": "concept", "title": "Source quality, reach, conversion, cost, speed, representation, accessibility, and relationship governance"}], "description": "This subtopic builds a diversified, measurable pipeline rather than relying on a single job board."}, {"id": "5d181b1b-cebc-4e2a-8bd2-da0db27ccbeb", "type": "subtopic", "title": "Inclusive and lawful recruiting communication", "children": [{"id": "2fc61fdc-2637-4426-acf6-3c468e721063", "type": "concept", "title": "Job-ad content, essential criteria, plain language, accessibility, accommodations, and equal-opportunity statements"}, {"id": "47ee64aa-b9b9-4963-9558-5ee754c4f3a7", "type": "concept", "title": "Avoiding exclusionary proxies, inflated requirements, discriminatory targeting, dark patterns, and misleading claims"}, {"id": "8fcac66b-274b-4882-8e58-c458ced865f2", "type": "concept", "title": "Applicant tracking, consent, privacy, response standards, candidate experience, and adverse-impact monitoring"}], "description": "Students create accurate, accessible recruitment materials and consistent applicant communication."}]}, {"id": "1a8a9be4-ca2c-48e9-a90e-5e03b2fde76c", "type": "topic", "title": "Selection, Assessment, Hiring, and Employment Eligibility", "description": "Selection should predict job performance, protect fairness, and withstand scrutiny. Students learn to combine valid evidence, structured judgment, legal controls, and respectful candidate experience.", "children": [{"id": "ad8fe17e-4b8d-44cb-b0dd-5447717e75fa", "type": "subtopic", "title": "Selection-system design and validity", "children": [{"id": "c30b7bf6-50c6-4a00-95fe-4f3cc006ab51", "type": "concept", "title": "Reliability, criterion/content/construct validity, utility, standardization, feasibility, and candidate reactions"}, {"id": "80848a87-2359-4d12-93cd-4306c3e4ad78", "type": "concept", "title": "Applications, work samples, simulations, situational judgment tests, cognitive/skills tests, and assessment centers"}, {"id": "3c4ba75c-acb8-4574-afaf-7c727d59e58e", "type": "concept", "title": "Multiple-hurdle versus compensatory models, cut scores, scoring rubrics, validation evidence, and documentation"}], "description": "Students choose methods based on job requirements and evidence, not intuition or convenience."}, {"id": "b48f596c-fe51-4c36-8196-a4732d6cf89e", "type": "subtopic", "title": "Structured interviewing and reference checks", "children": [{"id": "4cca7394-0d05-4862-a1f4-3b8b46aea487", "type": "concept", "title": "Behavioral and situational questions, anchored rating scales, interviewer training, panels, note taking, and calibration"}, {"id": "74bea1a4-1dfd-44b7-bced-0a3a7cf50e23", "type": "concept", "title": "Job-related probes, prohibited or risky questions, accommodation, language access, bias interrupters, and conflict disclosure"}, {"id": "2384b97a-cfce-4453-8fe1-524fb3d25b97", "type": "concept", "title": "Conditional offers, references, background checks, consent, relevance, consistency, privacy, and fair-chance considerations"}], "description": "Structured methods improve consistency and make hiring judgments more transparent and coachable."}, {"id": "1c4662a0-34e9-445e-92dc-7a0dbaa6f669", "type": "subtopic", "title": "Decision quality, adverse impact, and onboarding handoff", "children": [{"id": "b10aac97-21bf-49d9-9963-e876177e1c24", "type": "concept", "title": "Selection rates, four-fifths heuristic, statistical and practical significance, small samples, and job-related alternatives"}, {"id": "824e48fa-3c6f-4946-9697-7db5f8c0a6f2", "type": "concept", "title": "Offer terms, wage notice, classification, policies, Form I-9, record retention, and jurisdiction-specific requirements"}, {"id": "ba8bf0ff-597b-4be2-ad69-dbebfa223950", "type": "concept", "title": "Preboarding, first-day readiness, payroll/HRIS setup, accommodations, manager ownership, and early feedback"}], "description": "Students audit outcomes across groups and move selected candidates into a compliant, human-centered hiring process."}]}, {"id": "c4b69eeb-3a33-4d3a-93b2-3f74b5114841", "type": "topic", "title": "Onboarding, Learning, Service Culture, and Leadership Development", "description": "Learning systems turn promises and standards into safe, confident performance. In hospitality, effective development blends technical skill, guest judgment, culture, coaching, practice, feedback, and transfer to the shift.", "children": [{"id": "934de38b-1b45-4576-b4bb-350f80ce7a91", "type": "subtopic", "title": "Onboarding and organizational socialization", "children": [{"id": "d5042121-7601-4750-a940-e0e805bc7145", "type": "concept", "title": "Preboarding, welcome, role clarity, culture, standards, safety, payroll, benefits, policies, and technology access"}, {"id": "df41e196-ca80-46f7-948e-ce3a84af8d93", "type": "concept", "title": "Manager check-ins, buddy systems, job shadowing, practice, feedback, milestones, and accommodation follow-through"}, {"id": "51f8f722-af48-42b2-9cf7-5d1a437d6ab6", "type": "concept", "title": "New-hire experience measures, time to proficiency, early errors, absence, retention, and corrective redesign"}], "description": "Students design the first 30–90 days to build clarity, connection, competence, compliance, and confidence."}, {"id": "d9c19e65-fd1d-47df-a197-a6e356a94c94", "type": "subtopic", "title": "Training needs, design, and facilitation", "children": [{"id": "82d6a54d-baac-4f7d-a30b-65584e065980", "type": "concept", "title": "Organization, task, and person analysis; knowledge/skill/motivation/system gaps; priorities and constraints"}, {"id": "d8e23a67-fa0d-4b64-81cf-091ad7e1ff11", "type": "concept", "title": "Learning objectives, sequencing, demonstration, deliberate practice, scenarios, simulations, microlearning, and job aids"}, {"id": "95dc0b12-7aae-48fa-92c4-d175b437c855", "type": "concept", "title": "Inclusive facilitation, language and literacy, accessibility, psychological safety, feedback, and trainer preparation"}], "description": "This subtopic uses performance evidence to decide what training can solve and how adults learn best."}, {"id": "84d80800-580b-42c0-9068-cb808e199ef1", "type": "subtopic", "title": "Transfer, evaluation, and leadership pipeline", "children": [{"id": "d08c7fec-2fd0-49b8-bec6-45bc15b3ffab", "type": "concept", "title": "Manager reinforcement, opportunity to perform, coaching, communities of practice, nudges, and workflow integration"}, {"id": "d9d43042-dd0d-423b-8c29-8e0f598c8a6a", "type": "concept", "title": "Reaction, learning, behavior, results, control/comparison, attribution, benefit, cost, and return on expectations"}, {"id": "2eb4688c-1370-4189-ab49-aeda23124ec8", "type": "concept", "title": "Frontline-supervisor readiness, high-potential risk, mentoring, stretch assignments, leadership standards, and succession pools"}], "description": "Learning has value only when it changes behavior and results in the workplace."}]}, {"id": "31c865fa-eb4b-4d55-82fc-2244db5b0232", "type": "topic", "title": "Motivation, Engagement, Employee Experience, and Voice", "description": "Hospitality performance depends on sustained human energy under demanding guest-facing conditions. Students examine what creates meaningful effort, trust, belonging, recovery, and constructive voice.", "children": [{"id": "546438ba-38fe-4c82-963d-9938c2db9730", "type": "subtopic", "title": "Motivation and job attitudes", "children": [{"id": "4be0d6f8-d724-43e9-b882-90bbefe77be5", "type": "concept", "title": "Expectancy, equity, self-determination, goal-setting, reinforcement, job characteristics, and psychological contract"}, {"id": "8b1b6e12-7e86-46dd-8f37-dcb810f71e7a", "type": "concept", "title": "Intrinsic and extrinsic motivation, meaningful work, autonomy, mastery, purpose, recognition, and growth"}, {"id": "87158f0a-39f4-4fa9-ad13-29b54ed56c17", "type": "concept", "title": "Satisfaction, commitment, burnout, withdrawal, citizenship behavior, service sabotage, and intent to stay"}], "description": "Students compare theories and diagnose whether performance barriers arise from value, expectancy, fairness, goals, resources, or work design."}, {"id": "6772a3b4-34de-4857-afec-bf594c1b9780", "type": "subtopic", "title": "Employee listening and engagement action", "children": [{"id": "898f5d09-fc12-45ca-a4ac-0c5033a5d70b", "type": "concept", "title": "Pulse and census surveys, interviews, focus groups, stay interviews, suggestion systems, and digital listening"}, {"id": "5129cc5b-3cc8-4181-8389-e13865c6cdaf", "type": "concept", "title": "Constructs, item quality, response bias, anonymity, minimum reporting groups, segmentation, comments, and confidentiality"}, {"id": "b967d6cf-746f-46a7-8ef6-1a816b8c98dd", "type": "concept", "title": "Prioritization, local action plans, manager ownership, communication, follow-through, and impact evaluation"}], "description": "Surveys matter only when measures are trustworthy, results are interpreted responsibly, and managers act visibly."}, {"id": "e5521de5-5132-45b7-9a67-93f396e23a2c", "type": "subtopic", "title": "Voice, psychological safety, and service recovery", "children": [{"id": "8bc9c7d0-f053-4a9f-9f59-907a43cf8980", "type": "concept", "title": "Speaking up, error reporting, dissent, complaints, grievances, whistleblowing, open-door limits, and nonretaliation"}, {"id": "1d58066a-6e8b-497a-9e86-da61460d3a08", "type": "concept", "title": "Leader inclusiveness, respectful challenge, escalation paths, decision authority, just culture, and learning reviews"}, {"id": "b2012b4e-184a-494b-9587-0ab5925d9bab", "type": "concept", "title": "Employee empowerment boundaries, guest recovery discretion, resource access, handoffs, and after-action learning"}], "description": "Employees need safe ways to raise risks, challenge routines, and solve guest problems without fear of retaliation."}]}, {"id": "8083cf46-ad4a-48be-8076-75ecbe072e7d", "type": "topic", "title": "Performance Management, Coaching, and Accountability", "description": "Performance management aligns expectations, ongoing feedback, development, recognition, and fair consequences. The goal is better service and capability—not an annual form completed after the fact.", "children": [{"id": "80e4a2ff-576d-4fb7-bd8b-c9bdad3c8cd8", "type": "subtopic", "title": "Performance architecture and goal setting", "children": [{"id": "c0c40584-2b75-4009-9faf-e69b8f232c9b", "type": "concept", "title": "Results, behaviors, competencies, values, safety, quality, guest, team, financial, and learning measures"}, {"id": "a7096db2-3fb7-4b42-b67e-72abad0ee526", "type": "concept", "title": "Specific and challenging goals, controllability, line of sight, weighting, thresholds, stretch, and unintended incentives"}, {"id": "4d5ae9c7-bb49-4f2d-9f57-a082711d393f", "type": "concept", "title": "Role scorecards, check-ins, probationary reviews, project/shift feedback, and changing-goal governance"}], "description": "Students translate strategy and service standards into observable, balanced expectations."}, {"id": "7467d9bb-44eb-4ce7-869c-0db6e9d2f9f5", "type": "subtopic", "title": "Observation, feedback, and coaching", "children": [{"id": "57904e17-4c25-4c93-bd56-55a84cbc0bf8", "type": "concept", "title": "Direct observation, work records, guest feedback, peer input, calibration, recency/halo bias, and documentation"}, {"id": "7092a1dd-d753-4daa-b32f-fa9edafd9ea0", "type": "concept", "title": "Situation-behavior-impact, feedforward, active listening, questioning, empathy, cultural humility, and difficult conversations"}, {"id": "042728a6-5cf8-408e-926c-67bef9c26ad8", "type": "concept", "title": "Coaching plan, practice, resources, check-backs, reinforcement, recognition, and escalation triggers"}], "description": "Managers learn to gather evidence, discuss behavior and impact, listen, practice solutions, and support improvement."}, {"id": "85f1819a-c6c8-4e00-8fda-85019e7cd27c", "type": "subtopic", "title": "Appraisal, correction, and due process", "children": [{"id": "03e1ce6d-26ec-45ce-8198-17d6da79c193", "type": "concept", "title": "Rating scales, narrative evidence, calibration, forced distribution risks, appeals, and rater accountability"}, {"id": "ace94752-f3ef-494f-8b70-d302a1905dee", "type": "concept", "title": "Informal counseling, performance improvement plans, progressive discipline, consistency, mitigating factors, and final decisions"}, {"id": "43cc9b00-dbdb-40ca-9b7d-2f2df5c7fee0", "type": "concept", "title": "At-will doctrine limits, contract/union rules, protected activity, accommodation/leave interaction, records, and respectful separation"}], "description": "Students distinguish capability, conduct, system, health, and motivation issues before choosing an intervention."}]}, {"id": "1f730233-5e8b-4ecf-8e54-7c17ac185d23", "type": "topic", "title": "Compensation, Benefits, Tips, and Scheduling", "description": "Total rewards communicate what the organization values and shape attraction, fairness, retention, cost, and service. Hospitality adds complex issues of tips, service charges, fluctuating schedules, seasonality, and multi-job labor markets.", "children": [{"id": "52b81330-383a-4c5a-ab4f-28df2b6adf28", "type": "subtopic", "title": "Compensation strategy and job value", "children": [{"id": "82882884-dbce-46a6-be6e-cc9bfd0f79af", "type": "concept", "title": "Reward philosophy, market position, base pay, variable pay, premiums, bonuses, commissions, recognition, and noncash rewards"}, {"id": "290f66f2-cef9-4793-af34-0c7916388002", "type": "concept", "title": "Job evaluation, market pricing, pay grades/bands, ranges, compa-ratio, progression, compression, and geographic differentials"}, {"id": "00ba7db3-c798-4754-86ac-d1f85333df24", "type": "concept", "title": "Pay transparency, negotiation, discretion, governance, equity audits, communication, and manager training"}], "description": "Students balance external competitiveness, internal equity, affordability, compliance, and employee understanding."}, {"id": "b747f477-a4ab-4837-a964-26293ce454b0", "type": "subtopic", "title": "Wage-hour, tips, and service-charge controls", "children": [{"id": "03ac6b0c-2ce5-48b8-849c-2ad8e0d19d3e", "type": "concept", "title": "Employee/independent-contractor and exempt/nonexempt classification; hours worked; overtime; records; deductions"}, {"id": "9987f627-3901-4c4e-bafe-e3f9843a1583", "type": "concept", "title": "Tip credit, notice, tip pools, managers/supervisors, dual jobs, tip ownership, service charges, and credit-card fees"}, {"id": "50903869-2a53-4f01-a378-eb00b1aa23ff", "type": "concept", "title": "Meal/rest periods, uniforms, training time, travel, on-call time, youth employment, final pay, and local rules"}], "description": "This subtopic highlights U.S. hospitality pay risks that require current federal, state, local, and collective-agreement review."}, {"id": "6be83be6-4636-4993-9a10-f9ae0b55af1f", "type": "subtopic", "title": "Benefits, scheduling, and financial well-being", "children": [{"id": "92a8f56d-aaad-42c1-9226-fbb1407f289c", "type": "concept", "title": "Health, retirement, leave, paid time off, meals, transport, lodging, education, wellness, and voluntary benefits"}, {"id": "e19c7cc4-73e2-4b6c-9d17-d70fb3575a20", "type": "concept", "title": "Advance notice, availability, shift bidding, self-scheduling, split shifts, clopening, overtime, predictability, and shift swaps"}, {"id": "40ca8de8-2f8b-41ae-b8a3-33f0bb3a6d96", "type": "concept", "title": "Schedule quality, preference fulfillment, absenteeism, fatigue, turnover, labor cost, service outcomes, and fair-scheduling laws"}], "description": "Students design rewards and schedules around employee needs, service demand, fairness, and operating resilience."}]}, {"id": "c90ba22d-0f07-4d1e-afb0-590ed6a5b767", "type": "topic", "title": "Diversity, Equity, Inclusion, Accessibility, and Global Mindset", "description": "Inclusive hospitality teams serve diverse guests and communities, but business benefits never replace the fundamental duties of fairness and dignity. Students learn to remove barriers across the employee lifecycle.", "children": [{"id": "fd91192a-b51a-4f2f-9d95-b0c7db16ec54", "type": "subtopic", "title": "Systems of inclusion, equity, and belonging", "children": [{"id": "b7a16875-cb0d-43b9-9488-480c54779065", "type": "concept", "title": "Representation, inclusion, belonging, equity, equality, intersectionality, privilege, structural barriers, and allyship"}, {"id": "71d10aea-f757-4ba4-9d1e-37d6ad06c9de", "type": "concept", "title": "Lifecycle audits of sourcing, selection, assignment, schedules, pay, development, promotion, discipline, retention, and exit"}, {"id": "6feff15b-90a0-4052-9ae6-064c67c0d6d2", "type": "concept", "title": "Goals, accountability, employee resource groups, sponsorship, inclusive leadership, backlash risk, and evidence of impact"}], "description": "Students move beyond representation counts to examine access, treatment, voice, opportunity, advancement, and outcomes."}, {"id": "f9a15477-0d4c-436f-81f4-8d0b0bfeadee", "type": "subtopic", "title": "Bias, discrimination, harassment, and retaliation prevention", "children": [{"id": "83a24a11-b1b8-4db4-8402-f8f68f99c429", "type": "concept", "title": "Protected characteristics, disparate treatment, disparate impact, harassment, hostile environment, retaliation, and third-party conduct"}, {"id": "f5a2e8ca-54ba-4083-b3e2-43d8253f08b6", "type": "concept", "title": "Bias in criteria, referrals, interviews, schedules, guest preferences, appearance rules, language, algorithms, and informal networks"}, {"id": "82df4f3d-e2c2-4300-aac1-a76e80174e6d", "type": "concept", "title": "Policy, multiple reporting channels, bystander skills, manager response, interim safeguards, investigation, remedies, and monitoring"}], "description": "This subtopic combines legal awareness with practical prevention, reporting, response, and culture design."}, {"id": "3ac7b626-2cbf-4d81-8006-f56e5145a5c7", "type": "subtopic", "title": "Disability, religion, pregnancy, and other accommodations", "children": [{"id": "9dad58f2-3b90-4d4a-8bd2-2a75ca008445", "type": "concept", "title": "Request recognition, essential functions, dialogue, medical-information limits, options, effectiveness, undue hardship, and documentation"}, {"id": "a534c13e-d65a-4223-8c43-3d97f7337b5b", "type": "concept", "title": "Modified schedules, leave, equipment, communication access, task restructuring, reassignment, dress/grooming, prayer, and lactation"}, {"id": "12cccd4f-ed6d-4d7d-acbf-df0c1acc5904", "type": "concept", "title": "Accessibility in recruiting, learning, HR technology, emergency planning, employee events, facilities, and manager communication"}], "description": "Students practice the interactive, individualized process needed to identify reasonable work adjustments and protect confidentiality."}]}, {"id": "88ce3a74-6b50-47f4-aeea-477a3c1da822", "type": "topic", "title": "Employment Law, Employee Relations, Policies, and Investigations", "description": "U.S. hospitality managers operate amid overlapping federal, state, local, contract, and organizational rules. This section builds issue-spotting, documentation, fair process, and escalation habits—not legal self-confidence beyond one’s competence.", "children": [{"id": "1529cda5-49c2-4f7e-89e5-42ed29035e1a", "type": "subtopic", "title": "Employment-law architecture and issue spotting", "children": [{"id": "7751780d-e335-44b6-b457-2ce8620a4c5c", "type": "concept", "title": "At-will employment and exceptions; contracts; handbooks; wage-hour; discrimination; leave; safety; privacy; immigration; labor"}, {"id": "9ccc86a3-9127-4c26-afcd-f45bdc0f32b9", "type": "concept", "title": "Federal, state, local, tribal, and international layers; collective agreements; franchise/owner/operator responsibilities"}, {"id": "adcced8a-5643-45ee-8ec7-cbe18575594e", "type": "concept", "title": "Employee status, employer coverage, protected status/activity, adverse action, comparator, notice, documentation, preservation, and escalation"}], "description": "Students identify the source of a duty, relevant facts, jurisdiction, coverage, deadlines, and the need for qualified advice."}, {"id": "7d369afd-f763-48c1-bbfd-1efa0564d807", "type": "subtopic", "title": "Policy design and administration", "children": [{"id": "07ae26b3-9e7d-4c02-a631-be9ca123b56e", "type": "concept", "title": "Purpose, scope, definitions, responsibilities, standards, reporting, response, records, nonretaliation, exceptions, and contacts"}, {"id": "5d368ead-136f-4642-91d6-ebf37446e139", "type": "concept", "title": "Plain language, translation, accessibility, acknowledgments, training, version control, distribution, retention, and review cycle"}, {"id": "42698f08-eb4d-4c39-92a0-9a957d8fd561", "type": "concept", "title": "Consistency versus individualized accommodation, manager discretion, past practice, conflicts, waiver risk, and policy audits"}], "description": "A policy should set a clear purpose and process while preserving lawful discretion and consistent implementation."}, {"id": "188153c4-0b47-4b2f-a3c2-af704fae012b", "type": "subtopic", "title": "Complaints, workplace investigations, and corrective action", "children": [{"id": "7378cf74-8ed2-4fb2-b0dc-dc81e23e2500", "type": "concept", "title": "Intake, immediate safety, conflicts, scope, investigator independence, interim measures, preservation, and communication plan"}, {"id": "75c73aa2-1da9-4533-b8b2-c159213c7916", "type": "concept", "title": "Interview planning, credibility factors, corroboration, documents/digital evidence, confidentiality limits, standard of proof, and findings"}, {"id": "6e62e9b8-ba1e-4084-af87-ffcc4c70a79c", "type": "concept", "title": "Remedies, discipline, restoration, anti-retaliation monitoring, closure communication, lessons learned, and privilege/counsel boundaries"}], "description": "Students learn a neutral, timely, trauma-informed, and well-documented process that protects fairness and evidence."}]}, {"id": "3c922328-8696-4efa-bc40-7865c0db2c14", "type": "topic", "title": "Labor Relations, Collective Bargaining, and Employee Organizing", "description": "Labor relations includes employees’ rights to act together whether or not a workplace is unionized. Hospitality managers need lawful, respectful approaches to voice, organizing, bargaining, grievances, and operational continuity.", "children": [{"id": "6da3fa5c-2d1c-45a3-82c9-de2da5859e44", "type": "subtopic", "title": "Employee rights and organizing context", "children": [{"id": "f6e02bf1-f82e-44cf-b002-e7eb7c1b865a", "type": "concept", "title": "National Labor Relations Act coverage, protected concerted activity, union and nonunion settings, supervisors, and exclusions"}, {"id": "fdbc3638-38d2-452c-b5d0-c4ccf2331f99", "type": "concept", "title": "Wages, schedules, safety, tips, discipline, social media, petitions, walkouts, organizing, and third-party activity"}, {"id": "df7b821e-940f-43dc-8d41-63db146debe3", "type": "concept", "title": "Manager conduct, rapid escalation, documentation, neutrality/labor strategy, retaliation risk, and current NLRB guidance"}], "description": "Students recognize protected concerted activity and distinguish lawful manager communication from threats, interrogation, promises, or surveillance."}, {"id": "51aa34f2-58eb-4a09-935a-da0defaa33c0", "type": "subtopic", "title": "Representation and collective bargaining", "children": [{"id": "7273a8a2-3ead-4fd5-9bc3-875b10b98a6a", "type": "concept", "title": "Campaigns, petitions, bargaining units, elections/recognition, objections, certification, and first-contract challenges"}, {"id": "cf091a57-4399-4c49-a8de-c14552e8d301", "type": "concept", "title": "Mandatory, permissive, and prohibited subjects; proposals, costing, caucuses, package bargaining, impasse, mediation, and ratification"}, {"id": "0402393a-1cf0-4a2f-9f85-ea59dbefcab1", "type": "concept", "title": "Management rights, union security, dues, seniority, scheduling, subcontracting, technology, safety, discipline, and duration"}], "description": "This subtopic explains how a union becomes the representative and how parties negotiate terms and conditions in good faith."}, {"id": "0edce943-ca50-48dc-bb1b-bdf74f2cc6ab", "type": "subtopic", "title": "Contract administration, grievances, and conflict", "children": [{"id": "c6ff6f92-7316-4b81-a2f4-96f1962656ec", "type": "concept", "title": "Grievance steps, timelines, standing, information requests, steward rights, representation during interviews, and settlements"}, {"id": "09c36972-8490-4333-b869-8611b804cdef", "type": "concept", "title": "Just cause, notice, reasonable rule, investigation, proof, equal treatment, progressive discipline, and penalty"}, {"id": "632e0421-93f0-400c-ab89-f1498690d05c", "type": "concept", "title": "Arbitration, strikes, lockouts, picketing, contingency planning, guest/service continuity, safety, and relationship rebuilding"}], "description": "Students apply agreement language, past practice, evidence, and just-cause principles to daily decisions."}]}, {"id": "8040e01c-a39d-4ca8-8f42-706e9ebe0e4a", "type": "topic", "title": "Workplace Safety, Health, Well-Being, and Crisis Readiness", "description": "Safe work is a core employment condition and service prerequisite. Hospitality hazards include slips, burns, cuts, chemicals, ergonomics, heat, fatigue, violence, infectious disease, and psychological strain.", "children": [{"id": "ec25c560-a9ef-449c-8e82-de9f5ba5106e", "type": "subtopic", "title": "Safety management and hazard control", "children": [{"id": "0e4b2d39-c3d3-44f1-b253-d442d2c3a8a7", "type": "concept", "title": "Leadership commitment, worker participation, hazard identification, incident/near-miss reporting, inspections, and risk assessment"}, {"id": "4a79f32e-043b-421b-9f09-2832a90789ec", "type": "concept", "title": "Elimination, substitution, engineering controls, administrative controls, personal protective equipment, and residual risk"}, {"id": "8d996f80-b932-4e8f-b284-fbe432fc9384", "type": "concept", "title": "Housekeeping ergonomics, kitchen hazards, slips/falls, chemicals, heat, equipment, young workers, contractors, and emergency plans"}], "description": "Students use worker participation and the hierarchy of controls to prevent harm before relying on individual behavior."}, {"id": "aae68bf4-d46d-442b-9644-79a54ddba850", "type": "subtopic", "title": "Incident response, accommodation, and return to work", "children": [{"id": "7b3fd9f1-f5c4-4017-8883-dab6e1722bb3", "type": "concept", "title": "First aid/emergency response, scene control, notification, records, workers’ compensation, regulator reporting, and privacy"}, {"id": "a946ed9a-e88e-445b-9edc-78db56f8073a", "type": "concept", "title": "Root-cause learning, human factors, corrective actions, owner/due dates, verification, trend review, and nonretaliation"}, {"id": "9d80038f-7cbc-4ed1-aea7-6478c7551d09", "type": "concept", "title": "Functional abilities, temporary modifications, interactive accommodation, transitional work, case coordination, and relapse prevention"}], "description": "Managers must respond quickly, preserve care and evidence, meet reporting duties, and support safe recovery."}, {"id": "3264c068-c6d3-462f-a348-9aebdf8abd8b", "type": "subtopic", "title": "Well-being, fatigue, violence, and crisis readiness", "children": [{"id": "b8fba0b9-4441-427e-ac27-fae693d67584", "type": "concept", "title": "Workload, staffing, schedule quality, emotional labor, incivility, harassment, burnout, substance concerns, and employee assistance"}, {"id": "945a67b2-cdfa-4eec-a6a9-879ef356f214", "type": "concept", "title": "Workplace-violence assessment, late-night/cash/public-contact risks, de-escalation, duress, security, reporting, and post-event support"}, {"id": "f0f3c143-3202-4ddd-97c3-80dd1f925bed", "type": "concept", "title": "Severe weather, fire, health events, active threats, evacuation/shelter, communication, staffing continuity, drills, and after-action review"}], "description": "Students treat psychosocial risk and crisis capacity as operating-system issues, not resilience slogans."}]}, {"id": "ada56fcd-83e2-47d0-bf7c-5a91ce38ed71", "type": "topic", "title": "Retention, Career Development, Succession, and Workforce Resilience", "description": "Retention should focus on regrettable, preventable loss and on creating credible opportunities—not on keeping every employee indefinitely. Students connect mobility, manager quality, work design, rewards, and workforce resilience.", "children": [{"id": "86f12675-f520-42af-a6cc-59d345769a08", "type": "subtopic", "title": "Turnover diagnosis and retention strategy", "children": [{"id": "3d7881c1-7451-4db9-bcac-2e594c5607c0", "type": "concept", "title": "Turnover, stability, survival curves, cohort analysis, exit and stay data, absence, internal mobility, and vacancy cost"}, {"id": "6505dc8d-e504-43b5-8ce3-540ab2735da3", "type": "concept", "title": "Selection, onboarding, manager, pay, schedule, workload, fairness, safety, belonging, growth, commute, and life-stage drivers"}, {"id": "47fd9d7d-312f-4b45-a2e5-600223561561", "type": "concept", "title": "Segmented interventions, ethical retention, pilots, leading indicators, cost/benefit, controls, and unintended lock-in"}], "description": "Students distinguish voluntary/involuntary, regrettable/nonregrettable, avoidable/unavoidable, and early/tenured turnover."}, {"id": "c95fe457-dcf7-4573-84fe-47e1eae75a99", "type": "subtopic", "title": "Career architecture and internal mobility", "children": [{"id": "dee195f1-9aba-42a6-9831-9ea993df147e", "type": "concept", "title": "Career ladders and lattices, job families, levels, competencies, credentials, skill profiles, and transparent criteria"}, {"id": "ee911787-f6fa-4741-aaad-3de957d3525c", "type": "concept", "title": "Internal job markets, transfers, promotions, cross-training, stretch work, internships, mentoring, sponsorship, and tuition support"}, {"id": "cab473d1-f515-4f53-a5e0-4c8e2ec3d172", "type": "concept", "title": "Opportunity equity, manager talent hoarding, readiness, relocation, pay changes, replacement plans, and employee choice"}], "description": "Visible pathways help employees understand how skills and performance can lead to opportunity across departments, properties, brands, and functions."}, {"id": "51a0482f-36a8-4b73-bcdd-327cb93343fc", "type": "subtopic", "title": "Succession, critical roles, and workforce resilience", "children": [{"id": "84fa91a8-f5dc-4fae-9466-3550c16c46ee", "type": "concept", "title": "Critical roles and capabilities, vacancy risk, bench strength, readiness horizon, emergency successors, and single points of failure"}, {"id": "ebd89dfc-ded5-4665-b32b-fd5d236db993", "type": "concept", "title": "Talent reviews, evidence, calibration, potential versus performance, bias controls, development actions, and confidentiality"}, {"id": "b65f97e8-75aa-46fa-8161-11bd8cd5f729", "type": "concept", "title": "Cross-training, knowledge capture, communities of practice, contingent capacity, scenario plans, and plan effectiveness"}], "description": "Students prepare for leadership and skill continuity without treating succession charts as predictions."}]}, {"id": "3357dbdd-5efc-4206-9181-8fa5fd5f778e", "type": "topic", "title": "HR Technology, People Analytics, Responsible AI, and the Integrated HR Policy Case", "description": "Digital systems can improve access, consistency, insight, and employee service while also creating privacy, bias, security, surveillance, and vendor risks. The course culminates in an evidence-based people strategy and policy case.", "children": [{"id": "de61cf12-ee60-4f5a-b233-42606c91954b", "type": "subtopic", "title": "HR systems, employee service, and data governance", "children": [{"id": "3ad0bb5b-2bff-4ee1-b7fd-1f8060c2183d", "type": "concept", "title": "HRIS, payroll, timekeeping, scheduling, ATS, onboarding, LMS, performance, engagement, benefits, case management, and workforce management"}, {"id": "8a9acfb9-d3c6-464d-bc7d-93d69f0ec694", "type": "concept", "title": "Data ownership, purpose limitation, minimization, consent/notice, access, quality, retention, deletion, integration, and audit logs"}, {"id": "067a1dcd-865e-4073-a808-86ddb23efbaa", "type": "concept", "title": "Vendor due diligence, cybersecurity, business continuity, accessibility, localization, change management, adoption, and service measures"}], "description": "Students map the HR technology ecosystem and define trustworthy controls across the data lifecycle."}, {"id": "c23e8f3c-e7cb-400c-aa5d-a4f800106406", "type": "subtopic", "title": "People analytics and evidence-based decisions", "children": [{"id": "49c83ff4-e67d-44aa-a498-18317164341d", "type": "concept", "title": "Question, theory of change, metric definition, denominator, cohort, benchmark, segmentation, uncertainty, and data limitations"}, {"id": "2981b185-44ba-48df-b7dd-5460386bfe0d", "type": "concept", "title": "Descriptive, diagnostic, predictive, and prescriptive analytics; experiments, quasi-experiments, qualitative evidence, and triangulation"}, {"id": "e4bfd148-e956-42c4-972c-9c7716092509", "type": "concept", "title": "Selection, staffing, overtime, schedules, training, engagement, pay equity, performance, safety, turnover, and ROI use cases"}], "description": "Analytics begins with a decision and a causal question, not a dashboard full of correlations."}, {"id": "dfa6d2ff-163a-40d8-8a07-28ba1bddd8c5", "type": "subtopic", "title": "Responsible AI and integrated HR policy case", "children": [{"id": "a0ab68bd-b5c0-4e83-8c7f-ea2baa0efbd2", "type": "concept", "title": "Use-case inventory, human oversight, validity, bias/adverse impact, explainability, privacy, security, accessibility, drift, appeals, and vendor claims"}, {"id": "0e72c4ca-cb08-401e-848d-f986932c1b14", "type": "concept", "title": "NIST AI RMF govern-map-measure-manage logic; predeployment review, monitoring, incident response, documentation, and retirement"}, {"id": "d190e00f-c271-4061-8c4f-6c767473f061", "type": "concept", "title": "Capstone: issue statement, stakeholders, legal scan, evidence, alternatives, policy text, workflow, training, measures, risks, rollout, and review date"}], "description": "Students govern algorithmic tools and synthesize the course into a defensible policy and implementation recommendation."}]}], "dbBacked": true}$hrhjjson$::jsonb,
  true,
  false,
  'course',
  'public'
where not exists (
  select 1 from public.learning_paths where slug = 'human-resource-management-in-hospitality'
);

update public.learning_paths
set
  title = 'Human Resource Management in Hospitality',
  goal = 'Human Resource Management in Hospitality',
  summary = 'This course equips future hospitality managers to design and operate fair, lawful, inclusive, safe, and high-performing employment systems. Students forecast labor, analyze and design jobs, recruit and select talent, onboard and develop employees, create engagement and voice, manage performance, design rewards and schedules, administer employee and labor relations, protect safety and well-being, strengthen retention and succession, and use HR technology and people analytics responsibly. Applied cases culminate in an integrated people strategy and HR policy implementation plan.',
  data = $hrhjjson${"slug": "human-resource-management-in-hospitality", "title": "Human Resource Management in Hospitality", "description": "This course equips future hospitality managers to design and operate fair, lawful, inclusive, safe, and high-performing employment systems. Students forecast labor, analyze and design jobs, recruit and select talent, onboard and develop employees, create engagement and voice, manage performance, design rewards and schedules, administer employee and labor relations, protect safety and well-being, strengthen retention and succession, and use HR technology and people analytics responsibly. Applied cases culminate in an integrated people strategy and HR policy implementation plan.", "topics": [{"id": "b261e9fa-664b-4e42-933a-acc3cc893a36", "type": "topic", "title": "Strategic Human Resource Management and the Hospitality Employment System", "description": "Human resource management links the guest promise, operating model, workforce experience, legal duties, and business results. This section establishes HR as a strategic and ethical management system—not a collection of transactions.", "children": [{"id": "fd7921a6-6cde-45a5-922b-9541dc5b6583", "type": "subtopic", "title": "HR strategy and the service-profit logic", "children": [{"id": "3b29c145-ef9b-4b37-8771-c12592c62edc", "type": "concept", "title": "Business and brand strategy; guest promise; service concept; operating model; people implications"}, {"id": "7a66cce4-8c8d-4686-8c26-41daafbe31b1", "type": "concept", "title": "Employee experience, service climate, discretionary effort, service quality, guest loyalty, productivity, and value"}, {"id": "36ce906c-cc6e-4719-89e8-e6966e8406eb", "type": "concept", "title": "Strategic alignment, horizontal consistency among HR practices, tradeoffs, and unintended consequences"}], "description": "Students learn why staffing quality, employee capability, service climate, guest outcomes, and financial performance must be managed as one chain."}, {"id": "e0277bf8-9f8a-4429-9f3f-53d75e8fb002", "type": "subtopic", "title": "HR roles, operating model, and line-manager accountability", "children": [{"id": "561ada77-139d-476f-8fdd-b32cc4644929", "type": "concept", "title": "HR business partner, center of expertise, shared service, property HR, outsourced provider, and line manager roles"}, {"id": "a1ffd028-fc88-465e-9ce1-0cc63cfcfbb6", "type": "concept", "title": "Decision rights, service levels, escalation, documentation, confidentiality, and manager capability"}, {"id": "b199c1cc-5f6d-42ec-89c2-2c214dfec201", "type": "concept", "title": "Employee lifecycle: plan, attract, select, onboard, develop, deploy, reward, engage, retain, transition, and learn"}], "description": "This subtopic clarifies who owns workforce decisions across corporate, brand, regional, property, department, and shift levels."}, {"id": "5cb27bac-f486-4b6c-8d22-20cbfac185f4", "type": "subtopic", "title": "Ethical practice and stakeholder responsibilities", "children": [{"id": "ea6675b8-c95b-40c0-9f33-be870e7c0f2c", "type": "concept", "title": "Ethical reasoning, conflicts of interest, power asymmetry, consistency, procedural justice, and due process"}, {"id": "8808af37-71d1-4eee-9f1f-ef2f00744d8e", "type": "concept", "title": "Guests, employees, applicants, owners, managers, unions, contractors, communities, and regulators"}, {"id": "1961d9b0-b1d0-4b56-a01d-0a772e7119a2", "type": "concept", "title": "Speak-up channels, nonretaliation, records, conflicts, safeguards, remedies, and accountable leadership"}], "description": "Students practice balancing organizational goals with dignity, fairness, voice, safety, privacy, and community impact."}]}, {"id": "adddffcd-f5f3-42ec-a10b-71ea7eabce9a", "type": "topic", "title": "Service Workforce Planning, Job Analysis, and Work Design", "description": "Hospitality demand is variable, perishable, and labor intensive. Workforce planning converts forecasts and service standards into the right roles, skills, headcount, hours, and contingencies without treating people as interchangeable units.", "children": [{"id": "ae868140-a503-4810-ab59-1ca3bac00254", "type": "subtopic", "title": "Demand, labor, and skills forecasting", "children": [{"id": "cba74c0c-498e-46e5-bdc2-a2a5748d0f48", "type": "concept", "title": "Demand drivers, workload standards, labor hours per occupied room/cover, productivity, utilization, and service risk"}, {"id": "38cb05e2-40b9-415a-9366-186c07691722", "type": "concept", "title": "Headcount, FTE, hours, skill mix, fixed/variable labor, overtime, agency labor, and labor-cost percentage"}, {"id": "30c63f69-ca8a-4c14-bcca-d033659bb1bd", "type": "concept", "title": "Base/upside/downside scenarios, vacancy and absence buffers, peak planning, contingencies, and forecast error"}], "description": "Students translate occupancy, covers, events, seasonality, service level, and productivity assumptions into staffing requirements."}, {"id": "de2c4675-0a8d-40d8-b33c-1a7883b896e6", "type": "subtopic", "title": "Job analysis and competency modeling", "children": [{"id": "ea35d6fb-9d9d-4c6a-afbe-32df94414ff4", "type": "concept", "title": "Observation, interviews, diaries, critical incidents, workflow data, O*NET, and subject-matter validation"}, {"id": "b7975e9e-5752-493e-8457-02e2a6aeacc0", "type": "concept", "title": "Job description, person specification, essential versus marginal functions, physical/cognitive demands, and working conditions"}, {"id": "b775c244-ac18-4041-aa20-3d74e7703eee", "type": "concept", "title": "Technical, service, leadership, safety, digital, language, intercultural, and behavioral competencies"}], "description": "A defensible job system begins with evidence about work, essential functions, knowledge, skills, abilities, behaviors, and context."}, {"id": "c19038c1-8f17-4bcb-a2c9-ffd5ceba74aa", "type": "subtopic", "title": "Work design and employment architecture", "children": [{"id": "f81686bf-a60e-408d-b9a5-885de1b9c057", "type": "concept", "title": "Task variety, autonomy, feedback, interdependence, emotional labor, role clarity, workload, and ergonomics"}, {"id": "a229253f-ebcb-4d5e-80a6-7c8bc897561f", "type": "concept", "title": "Full-time, part-time, seasonal, on-call, temporary, contractor, franchise, and multi-property arrangements"}, {"id": "414420a9-bc35-4039-9d5b-c93e4ac8a598", "type": "concept", "title": "Cross-training, teams, job rotation, enrichment, scheduling flexibility, remote-capable work, and automation impacts"}], "description": "Students design work that supports service, safety, inclusion, learning, flexibility, and sustainable performance."}]}, {"id": "7d0abc36-3976-4ff0-bc3d-9a432b607129", "type": "topic", "title": "Employer Brand, Talent Sourcing, and Recruitment", "description": "Recruitment is a two-way market process: the organization seeks qualified talent while applicants judge credibility, fairness, work conditions, growth, and belonging. Hospitality employers must create realistic promises they can keep.", "children": [{"id": "2b00d154-73e8-48d7-86fa-f0fa6d09ed7f", "type": "subtopic", "title": "Employer value proposition and labor-market intelligence", "children": [{"id": "400701a9-ac29-40c0-b204-08923132ab7b", "type": "concept", "title": "Target talent segments, candidate personas, employee listening, competitor benchmarks, and local labor supply"}, {"id": "0fc77e1d-44b4-4c7b-ae61-21ddef3fbce3", "type": "concept", "title": "Pay, schedules, benefits, purpose, culture, manager quality, learning, mobility, well-being, and recognition"}, {"id": "2f83d2c9-93a7-4df1-94c4-6e81a279d38e", "type": "concept", "title": "Brand authenticity, employee reviews, reputation risk, realistic job previews, and promise-delivery gaps"}], "description": "Students define why target candidates would join, stay, and contribute—and test that promise against actual work."}, {"id": "9d163ba1-245a-4733-bf75-fd89416b795a", "type": "subtopic", "title": "Sourcing strategy and partnerships", "children": [{"id": "8982b299-e846-4577-ae0b-683e26f4a40e", "type": "concept", "title": "Internal mobility, referrals, schools, community groups, workforce agencies, associations, events, and digital channels"}, {"id": "d5daea6b-a64c-4b53-8408-849d9846b3d9", "type": "concept", "title": "Passive and active candidates, alumni, returners, seasonal pools, internships, apprenticeships, and international talent"}, {"id": "bbb5214e-655c-4a6d-8f8f-f0e645db2591", "type": "concept", "title": "Source quality, reach, conversion, cost, speed, representation, accessibility, and relationship governance"}], "description": "This subtopic builds a diversified, measurable pipeline rather than relying on a single job board."}, {"id": "5d181b1b-cebc-4e2a-8bd2-da0db27ccbeb", "type": "subtopic", "title": "Inclusive and lawful recruiting communication", "children": [{"id": "2fc61fdc-2637-4426-acf6-3c468e721063", "type": "concept", "title": "Job-ad content, essential criteria, plain language, accessibility, accommodations, and equal-opportunity statements"}, {"id": "47ee64aa-b9b9-4963-9558-5ee754c4f3a7", "type": "concept", "title": "Avoiding exclusionary proxies, inflated requirements, discriminatory targeting, dark patterns, and misleading claims"}, {"id": "8fcac66b-274b-4882-8e58-c458ced865f2", "type": "concept", "title": "Applicant tracking, consent, privacy, response standards, candidate experience, and adverse-impact monitoring"}], "description": "Students create accurate, accessible recruitment materials and consistent applicant communication."}]}, {"id": "1a8a9be4-ca2c-48e9-a90e-5e03b2fde76c", "type": "topic", "title": "Selection, Assessment, Hiring, and Employment Eligibility", "description": "Selection should predict job performance, protect fairness, and withstand scrutiny. Students learn to combine valid evidence, structured judgment, legal controls, and respectful candidate experience.", "children": [{"id": "ad8fe17e-4b8d-44cb-b0dd-5447717e75fa", "type": "subtopic", "title": "Selection-system design and validity", "children": [{"id": "c30b7bf6-50c6-4a00-95fe-4f3cc006ab51", "type": "concept", "title": "Reliability, criterion/content/construct validity, utility, standardization, feasibility, and candidate reactions"}, {"id": "80848a87-2359-4d12-93cd-4306c3e4ad78", "type": "concept", "title": "Applications, work samples, simulations, situational judgment tests, cognitive/skills tests, and assessment centers"}, {"id": "3c4ba75c-acb8-4574-afaf-7c727d59e58e", "type": "concept", "title": "Multiple-hurdle versus compensatory models, cut scores, scoring rubrics, validation evidence, and documentation"}], "description": "Students choose methods based on job requirements and evidence, not intuition or convenience."}, {"id": "b48f596c-fe51-4c36-8196-a4732d6cf89e", "type": "subtopic", "title": "Structured interviewing and reference checks", "children": [{"id": "4cca7394-0d05-4862-a1f4-3b8b46aea487", "type": "concept", "title": "Behavioral and situational questions, anchored rating scales, interviewer training, panels, note taking, and calibration"}, {"id": "74bea1a4-1dfd-44b7-bced-0a3a7cf50e23", "type": "concept", "title": "Job-related probes, prohibited or risky questions, accommodation, language access, bias interrupters, and conflict disclosure"}, {"id": "2384b97a-cfce-4453-8fe1-524fb3d25b97", "type": "concept", "title": "Conditional offers, references, background checks, consent, relevance, consistency, privacy, and fair-chance considerations"}], "description": "Structured methods improve consistency and make hiring judgments more transparent and coachable."}, {"id": "1c4662a0-34e9-445e-92dc-7a0dbaa6f669", "type": "subtopic", "title": "Decision quality, adverse impact, and onboarding handoff", "children": [{"id": "b10aac97-21bf-49d9-9963-e876177e1c24", "type": "concept", "title": "Selection rates, four-fifths heuristic, statistical and practical significance, small samples, and job-related alternatives"}, {"id": "824e48fa-3c6f-4946-9697-7db5f8c0a6f2", "type": "concept", "title": "Offer terms, wage notice, classification, policies, Form I-9, record retention, and jurisdiction-specific requirements"}, {"id": "ba8bf0ff-597b-4be2-ad69-dbebfa223950", "type": "concept", "title": "Preboarding, first-day readiness, payroll/HRIS setup, accommodations, manager ownership, and early feedback"}], "description": "Students audit outcomes across groups and move selected candidates into a compliant, human-centered hiring process."}]}, {"id": "c4b69eeb-3a33-4d3a-93b2-3f74b5114841", "type": "topic", "title": "Onboarding, Learning, Service Culture, and Leadership Development", "description": "Learning systems turn promises and standards into safe, confident performance. In hospitality, effective development blends technical skill, guest judgment, culture, coaching, practice, feedback, and transfer to the shift.", "children": [{"id": "934de38b-1b45-4576-b4bb-350f80ce7a91", "type": "subtopic", "title": "Onboarding and organizational socialization", "children": [{"id": "d5042121-7601-4750-a940-e0e805bc7145", "type": "concept", "title": "Preboarding, welcome, role clarity, culture, standards, safety, payroll, benefits, policies, and technology access"}, {"id": "df41e196-ca80-46f7-948e-ce3a84af8d93", "type": "concept", "title": "Manager check-ins, buddy systems, job shadowing, practice, feedback, milestones, and accommodation follow-through"}, {"id": "51f8f722-af48-42b2-9cf7-5d1a437d6ab6", "type": "concept", "title": "New-hire experience measures, time to proficiency, early errors, absence, retention, and corrective redesign"}], "description": "Students design the first 30–90 days to build clarity, connection, competence, compliance, and confidence."}, {"id": "d9c19e65-fd1d-47df-a197-a6e356a94c94", "type": "subtopic", "title": "Training needs, design, and facilitation", "children": [{"id": "82d6a54d-baac-4f7d-a30b-65584e065980", "type": "concept", "title": "Organization, task, and person analysis; knowledge/skill/motivation/system gaps; priorities and constraints"}, {"id": "d8e23a67-fa0d-4b64-81cf-091ad7e1ff11", "type": "concept", "title": "Learning objectives, sequencing, demonstration, deliberate practice, scenarios, simulations, microlearning, and job aids"}, {"id": "95dc0b12-7aae-48fa-92c4-d175b437c855", "type": "concept", "title": "Inclusive facilitation, language and literacy, accessibility, psychological safety, feedback, and trainer preparation"}], "description": "This subtopic uses performance evidence to decide what training can solve and how adults learn best."}, {"id": "84d80800-580b-42c0-9068-cb808e199ef1", "type": "subtopic", "title": "Transfer, evaluation, and leadership pipeline", "children": [{"id": "d08c7fec-2fd0-49b8-bec6-45bc15b3ffab", "type": "concept", "title": "Manager reinforcement, opportunity to perform, coaching, communities of practice, nudges, and workflow integration"}, {"id": "d9d43042-dd0d-423b-8c29-8e0f598c8a6a", "type": "concept", "title": "Reaction, learning, behavior, results, control/comparison, attribution, benefit, cost, and return on expectations"}, {"id": "2eb4688c-1370-4189-ab49-aeda23124ec8", "type": "concept", "title": "Frontline-supervisor readiness, high-potential risk, mentoring, stretch assignments, leadership standards, and succession pools"}], "description": "Learning has value only when it changes behavior and results in the workplace."}]}, {"id": "31c865fa-eb4b-4d55-82fc-2244db5b0232", "type": "topic", "title": "Motivation, Engagement, Employee Experience, and Voice", "description": "Hospitality performance depends on sustained human energy under demanding guest-facing conditions. Students examine what creates meaningful effort, trust, belonging, recovery, and constructive voice.", "children": [{"id": "546438ba-38fe-4c82-963d-9938c2db9730", "type": "subtopic", "title": "Motivation and job attitudes", "children": [{"id": "4be0d6f8-d724-43e9-b882-90bbefe77be5", "type": "concept", "title": "Expectancy, equity, self-determination, goal-setting, reinforcement, job characteristics, and psychological contract"}, {"id": "8b1b6e12-7e86-46dd-8f37-dcb810f71e7a", "type": "concept", "title": "Intrinsic and extrinsic motivation, meaningful work, autonomy, mastery, purpose, recognition, and growth"}, {"id": "87158f0a-39f4-4fa9-ad13-29b54ed56c17", "type": "concept", "title": "Satisfaction, commitment, burnout, withdrawal, citizenship behavior, service sabotage, and intent to stay"}], "description": "Students compare theories and diagnose whether performance barriers arise from value, expectancy, fairness, goals, resources, or work design."}, {"id": "6772a3b4-34de-4857-afec-bf594c1b9780", "type": "subtopic", "title": "Employee listening and engagement action", "children": [{"id": "898f5d09-fc12-45ca-a4ac-0c5033a5d70b", "type": "concept", "title": "Pulse and census surveys, interviews, focus groups, stay interviews, suggestion systems, and digital listening"}, {"id": "5129cc5b-3cc8-4181-8389-e13865c6cdaf", "type": "concept", "title": "Constructs, item quality, response bias, anonymity, minimum reporting groups, segmentation, comments, and confidentiality"}, {"id": "b967d6cf-746f-46a7-8ef6-1a816b8c98dd", "type": "concept", "title": "Prioritization, local action plans, manager ownership, communication, follow-through, and impact evaluation"}], "description": "Surveys matter only when measures are trustworthy, results are interpreted responsibly, and managers act visibly."}, {"id": "e5521de5-5132-45b7-9a67-93f396e23a2c", "type": "subtopic", "title": "Voice, psychological safety, and service recovery", "children": [{"id": "8bc9c7d0-f053-4a9f-9f59-907a43cf8980", "type": "concept", "title": "Speaking up, error reporting, dissent, complaints, grievances, whistleblowing, open-door limits, and nonretaliation"}, {"id": "1d58066a-6e8b-497a-9e86-da61460d3a08", "type": "concept", "title": "Leader inclusiveness, respectful challenge, escalation paths, decision authority, just culture, and learning reviews"}, {"id": "b2012b4e-184a-494b-9587-0ab5925d9bab", "type": "concept", "title": "Employee empowerment boundaries, guest recovery discretion, resource access, handoffs, and after-action learning"}], "description": "Employees need safe ways to raise risks, challenge routines, and solve guest problems without fear of retaliation."}]}, {"id": "8083cf46-ad4a-48be-8076-75ecbe072e7d", "type": "topic", "title": "Performance Management, Coaching, and Accountability", "description": "Performance management aligns expectations, ongoing feedback, development, recognition, and fair consequences. The goal is better service and capability—not an annual form completed after the fact.", "children": [{"id": "80e4a2ff-576d-4fb7-bd8b-c9bdad3c8cd8", "type": "subtopic", "title": "Performance architecture and goal setting", "children": [{"id": "c0c40584-2b75-4009-9faf-e69b8f232c9b", "type": "concept", "title": "Results, behaviors, competencies, values, safety, quality, guest, team, financial, and learning measures"}, {"id": "a7096db2-3fb7-4b42-b67e-72abad0ee526", "type": "concept", "title": "Specific and challenging goals, controllability, line of sight, weighting, thresholds, stretch, and unintended incentives"}, {"id": "4d5ae9c7-bb49-4f2d-9f57-a082711d393f", "type": "concept", "title": "Role scorecards, check-ins, probationary reviews, project/shift feedback, and changing-goal governance"}], "description": "Students translate strategy and service standards into observable, balanced expectations."}, {"id": "7467d9bb-44eb-4ce7-869c-0db6e9d2f9f5", "type": "subtopic", "title": "Observation, feedback, and coaching", "children": [{"id": "57904e17-4c25-4c93-bd56-55a84cbc0bf8", "type": "concept", "title": "Direct observation, work records, guest feedback, peer input, calibration, recency/halo bias, and documentation"}, {"id": "7092a1dd-d753-4daa-b32f-fa9edafd9ea0", "type": "concept", "title": "Situation-behavior-impact, feedforward, active listening, questioning, empathy, cultural humility, and difficult conversations"}, {"id": "042728a6-5cf8-408e-926c-67bef9c26ad8", "type": "concept", "title": "Coaching plan, practice, resources, check-backs, reinforcement, recognition, and escalation triggers"}], "description": "Managers learn to gather evidence, discuss behavior and impact, listen, practice solutions, and support improvement."}, {"id": "85f1819a-c6c8-4e00-8fda-85019e7cd27c", "type": "subtopic", "title": "Appraisal, correction, and due process", "children": [{"id": "03e1ce6d-26ec-45ce-8198-17d6da79c193", "type": "concept", "title": "Rating scales, narrative evidence, calibration, forced distribution risks, appeals, and rater accountability"}, {"id": "ace94752-f3ef-494f-8b70-d302a1905dee", "type": "concept", "title": "Informal counseling, performance improvement plans, progressive discipline, consistency, mitigating factors, and final decisions"}, {"id": "43cc9b00-dbdb-40ca-9b7d-2f2df5c7fee0", "type": "concept", "title": "At-will doctrine limits, contract/union rules, protected activity, accommodation/leave interaction, records, and respectful separation"}], "description": "Students distinguish capability, conduct, system, health, and motivation issues before choosing an intervention."}]}, {"id": "1f730233-5e8b-4ecf-8e54-7c17ac185d23", "type": "topic", "title": "Compensation, Benefits, Tips, and Scheduling", "description": "Total rewards communicate what the organization values and shape attraction, fairness, retention, cost, and service. Hospitality adds complex issues of tips, service charges, fluctuating schedules, seasonality, and multi-job labor markets.", "children": [{"id": "52b81330-383a-4c5a-ab4f-28df2b6adf28", "type": "subtopic", "title": "Compensation strategy and job value", "children": [{"id": "82882884-dbce-46a6-be6e-cc9bfd0f79af", "type": "concept", "title": "Reward philosophy, market position, base pay, variable pay, premiums, bonuses, commissions, recognition, and noncash rewards"}, {"id": "290f66f2-cef9-4793-af34-0c7916388002", "type": "concept", "title": "Job evaluation, market pricing, pay grades/bands, ranges, compa-ratio, progression, compression, and geographic differentials"}, {"id": "00ba7db3-c798-4754-86ac-d1f85333df24", "type": "concept", "title": "Pay transparency, negotiation, discretion, governance, equity audits, communication, and manager training"}], "description": "Students balance external competitiveness, internal equity, affordability, compliance, and employee understanding."}, {"id": "b747f477-a4ab-4837-a964-26293ce454b0", "type": "subtopic", "title": "Wage-hour, tips, and service-charge controls", "children": [{"id": "03ac6b0c-2ce5-48b8-849c-2ad8e0d19d3e", "type": "concept", "title": "Employee/independent-contractor and exempt/nonexempt classification; hours worked; overtime; records; deductions"}, {"id": "9987f627-3901-4c4e-bafe-e3f9843a1583", "type": "concept", "title": "Tip credit, notice, tip pools, managers/supervisors, dual jobs, tip ownership, service charges, and credit-card fees"}, {"id": "50903869-2a53-4f01-a378-eb00b1aa23ff", "type": "concept", "title": "Meal/rest periods, uniforms, training time, travel, on-call time, youth employment, final pay, and local rules"}], "description": "This subtopic highlights U.S. hospitality pay risks that require current federal, state, local, and collective-agreement review."}, {"id": "6be83be6-4636-4993-9a10-f9ae0b55af1f", "type": "subtopic", "title": "Benefits, scheduling, and financial well-being", "children": [{"id": "92a8f56d-aaad-42c1-9226-fbb1407f289c", "type": "concept", "title": "Health, retirement, leave, paid time off, meals, transport, lodging, education, wellness, and voluntary benefits"}, {"id": "e19c7cc4-73e2-4b6c-9d17-d70fb3575a20", "type": "concept", "title": "Advance notice, availability, shift bidding, self-scheduling, split shifts, clopening, overtime, predictability, and shift swaps"}, {"id": "40ca8de8-2f8b-41ae-b8a3-33f0bb3a6d96", "type": "concept", "title": "Schedule quality, preference fulfillment, absenteeism, fatigue, turnover, labor cost, service outcomes, and fair-scheduling laws"}], "description": "Students design rewards and schedules around employee needs, service demand, fairness, and operating resilience."}]}, {"id": "c90ba22d-0f07-4d1e-afb0-590ed6a5b767", "type": "topic", "title": "Diversity, Equity, Inclusion, Accessibility, and Global Mindset", "description": "Inclusive hospitality teams serve diverse guests and communities, but business benefits never replace the fundamental duties of fairness and dignity. Students learn to remove barriers across the employee lifecycle.", "children": [{"id": "fd91192a-b51a-4f2f-9d95-b0c7db16ec54", "type": "subtopic", "title": "Systems of inclusion, equity, and belonging", "children": [{"id": "b7a16875-cb0d-43b9-9488-480c54779065", "type": "concept", "title": "Representation, inclusion, belonging, equity, equality, intersectionality, privilege, structural barriers, and allyship"}, {"id": "71d10aea-f757-4ba4-9d1e-37d6ad06c9de", "type": "concept", "title": "Lifecycle audits of sourcing, selection, assignment, schedules, pay, development, promotion, discipline, retention, and exit"}, {"id": "6feff15b-90a0-4052-9ae6-064c67c0d6d2", "type": "concept", "title": "Goals, accountability, employee resource groups, sponsorship, inclusive leadership, backlash risk, and evidence of impact"}], "description": "Students move beyond representation counts to examine access, treatment, voice, opportunity, advancement, and outcomes."}, {"id": "f9a15477-0d4c-436f-81f4-8d0b0bfeadee", "type": "subtopic", "title": "Bias, discrimination, harassment, and retaliation prevention", "children": [{"id": "83a24a11-b1b8-4db4-8402-f8f68f99c429", "type": "concept", "title": "Protected characteristics, disparate treatment, disparate impact, harassment, hostile environment, retaliation, and third-party conduct"}, {"id": "f5a2e8ca-54ba-4083-b3e2-43d8253f08b6", "type": "concept", "title": "Bias in criteria, referrals, interviews, schedules, guest preferences, appearance rules, language, algorithms, and informal networks"}, {"id": "82df4f3d-e2c2-4300-aac1-a76e80174e6d", "type": "concept", "title": "Policy, multiple reporting channels, bystander skills, manager response, interim safeguards, investigation, remedies, and monitoring"}], "description": "This subtopic combines legal awareness with practical prevention, reporting, response, and culture design."}, {"id": "3ac7b626-2cbf-4d81-8006-f56e5145a5c7", "type": "subtopic", "title": "Disability, religion, pregnancy, and other accommodations", "children": [{"id": "9dad58f2-3b90-4d4a-8bd2-2a75ca008445", "type": "concept", "title": "Request recognition, essential functions, dialogue, medical-information limits, options, effectiveness, undue hardship, and documentation"}, {"id": "a534c13e-d65a-4223-8c43-3d97f7337b5b", "type": "concept", "title": "Modified schedules, leave, equipment, communication access, task restructuring, reassignment, dress/grooming, prayer, and lactation"}, {"id": "12cccd4f-ed6d-4d7d-acbf-df0c1acc5904", "type": "concept", "title": "Accessibility in recruiting, learning, HR technology, emergency planning, employee events, facilities, and manager communication"}], "description": "Students practice the interactive, individualized process needed to identify reasonable work adjustments and protect confidentiality."}]}, {"id": "88ce3a74-6b50-47f4-aeea-477a3c1da822", "type": "topic", "title": "Employment Law, Employee Relations, Policies, and Investigations", "description": "U.S. hospitality managers operate amid overlapping federal, state, local, contract, and organizational rules. This section builds issue-spotting, documentation, fair process, and escalation habits—not legal self-confidence beyond one’s competence.", "children": [{"id": "1529cda5-49c2-4f7e-89e5-42ed29035e1a", "type": "subtopic", "title": "Employment-law architecture and issue spotting", "children": [{"id": "7751780d-e335-44b6-b457-2ce8620a4c5c", "type": "concept", "title": "At-will employment and exceptions; contracts; handbooks; wage-hour; discrimination; leave; safety; privacy; immigration; labor"}, {"id": "9ccc86a3-9127-4c26-afcd-f45bdc0f32b9", "type": "concept", "title": "Federal, state, local, tribal, and international layers; collective agreements; franchise/owner/operator responsibilities"}, {"id": "adcced8a-5643-45ee-8ec7-cbe18575594e", "type": "concept", "title": "Employee status, employer coverage, protected status/activity, adverse action, comparator, notice, documentation, preservation, and escalation"}], "description": "Students identify the source of a duty, relevant facts, jurisdiction, coverage, deadlines, and the need for qualified advice."}, {"id": "7d369afd-f763-48c1-bbfd-1efa0564d807", "type": "subtopic", "title": "Policy design and administration", "children": [{"id": "07ae26b3-9e7d-4c02-a631-be9ca123b56e", "type": "concept", "title": "Purpose, scope, definitions, responsibilities, standards, reporting, response, records, nonretaliation, exceptions, and contacts"}, {"id": "5d368ead-136f-4642-91d6-ebf37446e139", "type": "concept", "title": "Plain language, translation, accessibility, acknowledgments, training, version control, distribution, retention, and review cycle"}, {"id": "42698f08-eb4d-4c39-92a0-9a957d8fd561", "type": "concept", "title": "Consistency versus individualized accommodation, manager discretion, past practice, conflicts, waiver risk, and policy audits"}], "description": "A policy should set a clear purpose and process while preserving lawful discretion and consistent implementation."}, {"id": "188153c4-0b47-4b2f-a3c2-af704fae012b", "type": "subtopic", "title": "Complaints, workplace investigations, and corrective action", "children": [{"id": "7378cf74-8ed2-4fb2-b0dc-dc81e23e2500", "type": "concept", "title": "Intake, immediate safety, conflicts, scope, investigator independence, interim measures, preservation, and communication plan"}, {"id": "75c73aa2-1da9-4533-b8b2-c159213c7916", "type": "concept", "title": "Interview planning, credibility factors, corroboration, documents/digital evidence, confidentiality limits, standard of proof, and findings"}, {"id": "6e62e9b8-ba1e-4084-af87-ffcc4c70a79c", "type": "concept", "title": "Remedies, discipline, restoration, anti-retaliation monitoring, closure communication, lessons learned, and privilege/counsel boundaries"}], "description": "Students learn a neutral, timely, trauma-informed, and well-documented process that protects fairness and evidence."}]}, {"id": "3c922328-8696-4efa-bc40-7865c0db2c14", "type": "topic", "title": "Labor Relations, Collective Bargaining, and Employee Organizing", "description": "Labor relations includes employees’ rights to act together whether or not a workplace is unionized. Hospitality managers need lawful, respectful approaches to voice, organizing, bargaining, grievances, and operational continuity.", "children": [{"id": "6da3fa5c-2d1c-45a3-82c9-de2da5859e44", "type": "subtopic", "title": "Employee rights and organizing context", "children": [{"id": "f6e02bf1-f82e-44cf-b002-e7eb7c1b865a", "type": "concept", "title": "National Labor Relations Act coverage, protected concerted activity, union and nonunion settings, supervisors, and exclusions"}, {"id": "fdbc3638-38d2-452c-b5d0-c4ccf2331f99", "type": "concept", "title": "Wages, schedules, safety, tips, discipline, social media, petitions, walkouts, organizing, and third-party activity"}, {"id": "df7b821e-940f-43dc-8d41-63db146debe3", "type": "concept", "title": "Manager conduct, rapid escalation, documentation, neutrality/labor strategy, retaliation risk, and current NLRB guidance"}], "description": "Students recognize protected concerted activity and distinguish lawful manager communication from threats, interrogation, promises, or surveillance."}, {"id": "51aa34f2-58eb-4a09-935a-da0defaa33c0", "type": "subtopic", "title": "Representation and collective bargaining", "children": [{"id": "7273a8a2-3ead-4fd5-9bc3-875b10b98a6a", "type": "concept", "title": "Campaigns, petitions, bargaining units, elections/recognition, objections, certification, and first-contract challenges"}, {"id": "cf091a57-4399-4c49-a8de-c14552e8d301", "type": "concept", "title": "Mandatory, permissive, and prohibited subjects; proposals, costing, caucuses, package bargaining, impasse, mediation, and ratification"}, {"id": "0402393a-1cf0-4a2f-9f85-ea59dbefcab1", "type": "concept", "title": "Management rights, union security, dues, seniority, scheduling, subcontracting, technology, safety, discipline, and duration"}], "description": "This subtopic explains how a union becomes the representative and how parties negotiate terms and conditions in good faith."}, {"id": "0edce943-ca50-48dc-bb1b-bdf74f2cc6ab", "type": "subtopic", "title": "Contract administration, grievances, and conflict", "children": [{"id": "c6ff6f92-7316-4b81-a2f4-96f1962656ec", "type": "concept", "title": "Grievance steps, timelines, standing, information requests, steward rights, representation during interviews, and settlements"}, {"id": "09c36972-8490-4333-b869-8611b804cdef", "type": "concept", "title": "Just cause, notice, reasonable rule, investigation, proof, equal treatment, progressive discipline, and penalty"}, {"id": "632e0421-93f0-400c-ab89-f1498690d05c", "type": "concept", "title": "Arbitration, strikes, lockouts, picketing, contingency planning, guest/service continuity, safety, and relationship rebuilding"}], "description": "Students apply agreement language, past practice, evidence, and just-cause principles to daily decisions."}]}, {"id": "8040e01c-a39d-4ca8-8f42-706e9ebe0e4a", "type": "topic", "title": "Workplace Safety, Health, Well-Being, and Crisis Readiness", "description": "Safe work is a core employment condition and service prerequisite. Hospitality hazards include slips, burns, cuts, chemicals, ergonomics, heat, fatigue, violence, infectious disease, and psychological strain.", "children": [{"id": "ec25c560-a9ef-449c-8e82-de9f5ba5106e", "type": "subtopic", "title": "Safety management and hazard control", "children": [{"id": "0e4b2d39-c3d3-44f1-b253-d442d2c3a8a7", "type": "concept", "title": "Leadership commitment, worker participation, hazard identification, incident/near-miss reporting, inspections, and risk assessment"}, {"id": "4a79f32e-043b-421b-9f09-2832a90789ec", "type": "concept", "title": "Elimination, substitution, engineering controls, administrative controls, personal protective equipment, and residual risk"}, {"id": "8d996f80-b932-4e8f-b284-fbe432fc9384", "type": "concept", "title": "Housekeeping ergonomics, kitchen hazards, slips/falls, chemicals, heat, equipment, young workers, contractors, and emergency plans"}], "description": "Students use worker participation and the hierarchy of controls to prevent harm before relying on individual behavior."}, {"id": "aae68bf4-d46d-442b-9644-79a54ddba850", "type": "subtopic", "title": "Incident response, accommodation, and return to work", "children": [{"id": "7b3fd9f1-f5c4-4017-8883-dab6e1722bb3", "type": "concept", "title": "First aid/emergency response, scene control, notification, records, workers’ compensation, regulator reporting, and privacy"}, {"id": "a946ed9a-e88e-445b-9edc-78db56f8073a", "type": "concept", "title": "Root-cause learning, human factors, corrective actions, owner/due dates, verification, trend review, and nonretaliation"}, {"id": "9d80038f-7cbc-4ed1-aea7-6478c7551d09", "type": "concept", "title": "Functional abilities, temporary modifications, interactive accommodation, transitional work, case coordination, and relapse prevention"}], "description": "Managers must respond quickly, preserve care and evidence, meet reporting duties, and support safe recovery."}, {"id": "3264c068-c6d3-462f-a348-9aebdf8abd8b", "type": "subtopic", "title": "Well-being, fatigue, violence, and crisis readiness", "children": [{"id": "b8fba0b9-4441-427e-ac27-fae693d67584", "type": "concept", "title": "Workload, staffing, schedule quality, emotional labor, incivility, harassment, burnout, substance concerns, and employee assistance"}, {"id": "945a67b2-cdfa-4eec-a6a9-879ef356f214", "type": "concept", "title": "Workplace-violence assessment, late-night/cash/public-contact risks, de-escalation, duress, security, reporting, and post-event support"}, {"id": "f0f3c143-3202-4ddd-97c3-80dd1f925bed", "type": "concept", "title": "Severe weather, fire, health events, active threats, evacuation/shelter, communication, staffing continuity, drills, and after-action review"}], "description": "Students treat psychosocial risk and crisis capacity as operating-system issues, not resilience slogans."}]}, {"id": "ada56fcd-83e2-47d0-bf7c-5a91ce38ed71", "type": "topic", "title": "Retention, Career Development, Succession, and Workforce Resilience", "description": "Retention should focus on regrettable, preventable loss and on creating credible opportunities—not on keeping every employee indefinitely. Students connect mobility, manager quality, work design, rewards, and workforce resilience.", "children": [{"id": "86f12675-f520-42af-a6cc-59d345769a08", "type": "subtopic", "title": "Turnover diagnosis and retention strategy", "children": [{"id": "3d7881c1-7451-4db9-bcac-2e594c5607c0", "type": "concept", "title": "Turnover, stability, survival curves, cohort analysis, exit and stay data, absence, internal mobility, and vacancy cost"}, {"id": "6505dc8d-e504-43b5-8ce3-540ab2735da3", "type": "concept", "title": "Selection, onboarding, manager, pay, schedule, workload, fairness, safety, belonging, growth, commute, and life-stage drivers"}, {"id": "47fd9d7d-312f-4b45-a2e5-600223561561", "type": "concept", "title": "Segmented interventions, ethical retention, pilots, leading indicators, cost/benefit, controls, and unintended lock-in"}], "description": "Students distinguish voluntary/involuntary, regrettable/nonregrettable, avoidable/unavoidable, and early/tenured turnover."}, {"id": "c95fe457-dcf7-4573-84fe-47e1eae75a99", "type": "subtopic", "title": "Career architecture and internal mobility", "children": [{"id": "dee195f1-9aba-42a6-9831-9ea993df147e", "type": "concept", "title": "Career ladders and lattices, job families, levels, competencies, credentials, skill profiles, and transparent criteria"}, {"id": "ee911787-f6fa-4741-aaad-3de957d3525c", "type": "concept", "title": "Internal job markets, transfers, promotions, cross-training, stretch work, internships, mentoring, sponsorship, and tuition support"}, {"id": "cab473d1-f515-4f53-a5e0-4c8e2ec3d172", "type": "concept", "title": "Opportunity equity, manager talent hoarding, readiness, relocation, pay changes, replacement plans, and employee choice"}], "description": "Visible pathways help employees understand how skills and performance can lead to opportunity across departments, properties, brands, and functions."}, {"id": "51a0482f-36a8-4b73-bcdd-327cb93343fc", "type": "subtopic", "title": "Succession, critical roles, and workforce resilience", "children": [{"id": "84fa91a8-f5dc-4fae-9466-3550c16c46ee", "type": "concept", "title": "Critical roles and capabilities, vacancy risk, bench strength, readiness horizon, emergency successors, and single points of failure"}, {"id": "ebd89dfc-ded5-4665-b32b-fd5d236db993", "type": "concept", "title": "Talent reviews, evidence, calibration, potential versus performance, bias controls, development actions, and confidentiality"}, {"id": "b65f97e8-75aa-46fa-8161-11bd8cd5f729", "type": "concept", "title": "Cross-training, knowledge capture, communities of practice, contingent capacity, scenario plans, and plan effectiveness"}], "description": "Students prepare for leadership and skill continuity without treating succession charts as predictions."}]}, {"id": "3357dbdd-5efc-4206-9181-8fa5fd5f778e", "type": "topic", "title": "HR Technology, People Analytics, Responsible AI, and the Integrated HR Policy Case", "description": "Digital systems can improve access, consistency, insight, and employee service while also creating privacy, bias, security, surveillance, and vendor risks. The course culminates in an evidence-based people strategy and policy case.", "children": [{"id": "de61cf12-ee60-4f5a-b233-42606c91954b", "type": "subtopic", "title": "HR systems, employee service, and data governance", "children": [{"id": "3ad0bb5b-2bff-4ee1-b7fd-1f8060c2183d", "type": "concept", "title": "HRIS, payroll, timekeeping, scheduling, ATS, onboarding, LMS, performance, engagement, benefits, case management, and workforce management"}, {"id": "8a9acfb9-d3c6-464d-bc7d-93d69f0ec694", "type": "concept", "title": "Data ownership, purpose limitation, minimization, consent/notice, access, quality, retention, deletion, integration, and audit logs"}, {"id": "067a1dcd-865e-4073-a808-86ddb23efbaa", "type": "concept", "title": "Vendor due diligence, cybersecurity, business continuity, accessibility, localization, change management, adoption, and service measures"}], "description": "Students map the HR technology ecosystem and define trustworthy controls across the data lifecycle."}, {"id": "c23e8f3c-e7cb-400c-aa5d-a4f800106406", "type": "subtopic", "title": "People analytics and evidence-based decisions", "children": [{"id": "49c83ff4-e67d-44aa-a498-18317164341d", "type": "concept", "title": "Question, theory of change, metric definition, denominator, cohort, benchmark, segmentation, uncertainty, and data limitations"}, {"id": "2981b185-44ba-48df-b7dd-5460386bfe0d", "type": "concept", "title": "Descriptive, diagnostic, predictive, and prescriptive analytics; experiments, quasi-experiments, qualitative evidence, and triangulation"}, {"id": "e4bfd148-e956-42c4-972c-9c7716092509", "type": "concept", "title": "Selection, staffing, overtime, schedules, training, engagement, pay equity, performance, safety, turnover, and ROI use cases"}], "description": "Analytics begins with a decision and a causal question, not a dashboard full of correlations."}, {"id": "dfa6d2ff-163a-40d8-8a07-28ba1bddd8c5", "type": "subtopic", "title": "Responsible AI and integrated HR policy case", "children": [{"id": "a0ab68bd-b5c0-4e83-8c7f-ea2baa0efbd2", "type": "concept", "title": "Use-case inventory, human oversight, validity, bias/adverse impact, explainability, privacy, security, accessibility, drift, appeals, and vendor claims"}, {"id": "0e72c4ca-cb08-401e-848d-f986932c1b14", "type": "concept", "title": "NIST AI RMF govern-map-measure-manage logic; predeployment review, monitoring, incident response, documentation, and retirement"}, {"id": "d190e00f-c271-4061-8c4f-6c767473f061", "type": "concept", "title": "Capstone: issue statement, stakeholders, legal scan, evidence, alternatives, policy text, workflow, training, measures, risks, rollout, and review date"}], "description": "Students govern algorithmic tools and synthesize the course into a defensible policy and implementation recommendation."}]}], "dbBacked": true}$hrhjjson$::jsonb,
