insert into public.curated_courses (id, slug, title, description)
insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('b261e9fa-664b-4e42-933a-acc3cc893a36', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', null, 'topic'::public.curated_course_node_type, 'Strategic Human Resource Management and the Hospitality Employment System', 'Human resource management links the guest promise, operating model, workforce experience, legal duties, and business results. This section establishes HR as a strategic and ethical management system—not a collection of transactions.', 0),
  ('fd7921a6-6cde-45a5-922b-9541dc5b6583', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', 'b261e9fa-664b-4e42-933a-acc3cc893a36', 'subtopic'::public.curated_course_node_type, 'HR strategy and the service-profit logic', 'Students learn why staffing quality, employee capability, service climate, guest outcomes, and financial performance must be managed as one chain.', 0),
  ('3b29c145-ef9b-4b37-8771-c12592c62edc', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', 'fd7921a6-6cde-45a5-922b-9541dc5b6583', 'concept'::public.curated_course_node_type, 'Business and brand strategy; guest promise; service concept; operating model; people implications', null, 0),
  ('7a66cce4-8c8d-4686-8c26-41daafbe31b1', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', 'fd7921a6-6cde-45a5-922b-9541dc5b6583', 'concept'::public.curated_course_node_type, 'Employee experience, service climate, discretionary effort, service quality, guest loyalty, productivity, and value', null, 1),
  ('36ce906c-cc6e-4719-89e8-e6966e8406eb', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', 'fd7921a6-6cde-45a5-922b-9541dc5b6583', 'concept'::public.curated_course_node_type, 'Strategic alignment, horizontal consistency among HR practices, tradeoffs, and unintended consequences', null, 2),
  ('e0277bf8-9f8a-4429-9f3f-53d75e8fb002', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', 'b261e9fa-664b-4e42-933a-acc3cc893a36', 'subtopic'::public.curated_course_node_type, 'HR roles, operating model, and line-manager accountability', 'This subtopic clarifies who owns workforce decisions across corporate, brand, regional, property, department, and shift levels.', 1),
  ('561ada77-139d-476f-8fdd-b32cc4644929', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', 'e0277bf8-9f8a-4429-9f3f-53d75e8fb002', 'concept'::public.curated_course_node_type, 'HR business partner, center of expertise, shared service, property HR, outsourced provider, and line manager roles', null, 0),
  ('a1ffd028-fc88-465e-9ce1-0cc63cfcfbb6', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', 'e0277bf8-9f8a-4429-9f3f-53d75e8fb002', 'concept'::public.curated_course_node_type, 'Decision rights, service levels, escalation, documentation, confidentiality, and manager capability', null, 1),
  ('b199c1cc-5f6d-42ec-89c2-2c214dfec201', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', 'e0277bf8-9f8a-4429-9f3f-53d75e8fb002', 'concept'::public.curated_course_node_type, 'Employee lifecycle: plan, attract, select, onboard, develop, deploy, reward, engage, retain, transition, and learn', null, 2),
  ('5cb27bac-f486-4b6c-8d22-20cbfac185f4', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', 'b261e9fa-664b-4e42-933a-acc3cc893a36', 'subtopic'::public.curated_course_node_type, 'Ethical practice and stakeholder responsibilities', 'Students practice balancing organizational goals with dignity, fairness, voice, safety, privacy, and community impact.', 2),
  ('ea6675b8-c95b-40c0-9f33-be870e7c0f2c', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', '5cb27bac-f486-4b6c-8d22-20cbfac185f4', 'concept'::public.curated_course_node_type, 'Ethical reasoning, conflicts of interest, power asymmetry, consistency, procedural justice, and due process', null, 0),
  ('8808af37-71d1-4eee-9f1f-ef2f00744d8e', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', '5cb27bac-f486-4b6c-8d22-20cbfac185f4', 'concept'::public.curated_course_node_type, 'Guests, employees, applicants, owners, managers, unions, contractors, communities, and regulators', null, 1),
  ('1961d9b0-b1d0-4b56-a01d-0a772e7119a2', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', '5cb27bac-f486-4b6c-8d22-20cbfac185f4', 'concept'::public.curated_course_node_type, 'Speak-up channels, nonretaliation, records, conflicts, safeguards, remedies, and accountable leadership', null, 2),
  ('adddffcd-f5f3-42ec-a10b-71ea7eabce9a', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', null, 'topic'::public.curated_course_node_type, 'Service Workforce Planning, Job Analysis, and Work Design', 'Hospitality demand is variable, perishable, and labor intensive. Workforce planning converts forecasts and service standards into the right roles, skills, headcount, hours, and contingencies without treating people as interchangeable units.', 1),
  ('ae868140-a503-4810-ab59-1ca3bac00254', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', 'adddffcd-f5f3-42ec-a10b-71ea7eabce9a', 'subtopic'::public.curated_course_node_type, 'Demand, labor, and skills forecasting', 'Students translate occupancy, covers, events, seasonality, service level, and productivity assumptions into staffing requirements.', 0),
  ('cba74c0c-498e-46e5-bdc2-a2a5748d0f48', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', 'ae868140-a503-4810-ab59-1ca3bac00254', 'concept'::public.curated_course_node_type, 'Demand drivers, workload standards, labor hours per occupied room/cover, productivity, utilization, and service risk', null, 0),
  ('38cb05e2-40b9-415a-9366-186c07691722', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', 'ae868140-a503-4810-ab59-1ca3bac00254', 'concept'::public.curated_course_node_type, 'Headcount, FTE, hours, skill mix, fixed/variable labor, overtime, agency labor, and labor-cost percentage', null, 1),
  ('30c63f69-ca8a-4c14-bcca-d033659bb1bd', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', 'ae868140-a503-4810-ab59-1ca3bac00254', 'concept'::public.curated_course_node_type, 'Base/upside/downside scenarios, vacancy and absence buffers, peak planning, contingencies, and forecast error', null, 2),
  ('de2c4675-0a8d-40d8-b33c-1a7883b896e6', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', 'adddffcd-f5f3-42ec-a10b-71ea7eabce9a', 'subtopic'::public.curated_course_node_type, 'Job analysis and competency modeling', 'A defensible job system begins with evidence about work, essential functions, knowledge, skills, abilities, behaviors, and context.', 1),
  ('ea35d6fb-9d9d-4c6a-afbe-32df94414ff4', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', 'de2c4675-0a8d-40d8-b33c-1a7883b896e6', 'concept'::public.curated_course_node_type, 'Observation, interviews, diaries, critical incidents, workflow data, O*NET, and subject-matter validation', null, 0),
  ('b7975e9e-5752-493e-8457-02e2a6aeacc0', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', 'de2c4675-0a8d-40d8-b33c-1a7883b896e6', 'concept'::public.curated_course_node_type, 'Job description, person specification, essential versus marginal functions, physical/cognitive demands, and working conditions', null, 1),
  ('b775c244-ac18-4041-aa20-3d74e7703eee', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', 'de2c4675-0a8d-40d8-b33c-1a7883b896e6', 'concept'::public.curated_course_node_type, 'Technical, service, leadership, safety, digital, language, intercultural, and behavioral competencies', null, 2),
  ('c19038c1-8f17-4bcb-a2c9-ffd5ceba74aa', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', 'adddffcd-f5f3-42ec-a10b-71ea7eabce9a', 'subtopic'::public.curated_course_node_type, 'Work design and employment architecture', 'Students design work that supports service, safety, inclusion, learning, flexibility, and sustainable performance.', 2),
  ('f81686bf-a60e-408d-b9a5-885de1b9c057', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', 'c19038c1-8f17-4bcb-a2c9-ffd5ceba74aa', 'concept'::public.curated_course_node_type, 'Task variety, autonomy, feedback, interdependence, emotional labor, role clarity, workload, and ergonomics', null, 0),
  ('a229253f-ebcb-4d5e-80a6-7c8bc897561f', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', 'c19038c1-8f17-4bcb-a2c9-ffd5ceba74aa', 'concept'::public.curated_course_node_type, 'Full-time, part-time, seasonal, on-call, temporary, contractor, franchise, and multi-property arrangements', null, 1),
  ('414420a9-bc35-4039-9d5b-c93e4ac8a598', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', 'c19038c1-8f17-4bcb-a2c9-ffd5ceba74aa', 'concept'::public.curated_course_node_type, 'Cross-training, teams, job rotation, enrichment, scheduling flexibility, remote-capable work, and automation impacts', null, 2),
  ('7d0abc36-3976-4ff0-bc3d-9a432b607129', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', null, 'topic'::public.curated_course_node_type, 'Employer Brand, Talent Sourcing, and Recruitment', 'Recruitment is a two-way market process: the organization seeks qualified talent while applicants judge credibility, fairness, work conditions, growth, and belonging. Hospitality employers must create realistic promises they can keep.', 2),
  ('2b00d154-73e8-48d7-86fa-f0fa6d09ed7f', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', '7d0abc36-3976-4ff0-bc3d-9a432b607129', 'subtopic'::public.curated_course_node_type, 'Employer value proposition and labor-market intelligence', 'Students define why target candidates would join, stay, and contribute—and test that promise against actual work.', 0),
  ('400701a9-ac29-40c0-b204-08923132ab7b', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', '2b00d154-73e8-48d7-86fa-f0fa6d09ed7f', 'concept'::public.curated_course_node_type, 'Target talent segments, candidate personas, employee listening, competitor benchmarks, and local labor supply', null, 0),
  ('0fc77e1d-44b4-4c7b-ae61-21ddef3fbce3', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', '2b00d154-73e8-48d7-86fa-f0fa6d09ed7f', 'concept'::public.curated_course_node_type, 'Pay, schedules, benefits, purpose, culture, manager quality, learning, mobility, well-being, and recognition', null, 1),
  ('2f83d2c9-93a7-4df1-94c4-6e81a279d38e', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', '2b00d154-73e8-48d7-86fa-f0fa6d09ed7f', 'concept'::public.curated_course_node_type, 'Brand authenticity, employee reviews, reputation risk, realistic job previews, and promise-delivery gaps', null, 2),
  ('9d163ba1-245a-4733-bf75-fd89416b795a', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', '7d0abc36-3976-4ff0-bc3d-9a432b607129', 'subtopic'::public.curated_course_node_type, 'Sourcing strategy and partnerships', 'This subtopic builds a diversified, measurable pipeline rather than relying on a single job board.', 1),
  ('8982b299-e846-4577-ae0b-683e26f4a40e', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', '9d163ba1-245a-4733-bf75-fd89416b795a', 'concept'::public.curated_course_node_type, 'Internal mobility, referrals, schools, community groups, workforce agencies, associations, events, and digital channels', null, 0),
  ('d5daea6b-a64c-4b53-8408-849d9846b3d9', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', '9d163ba1-245a-4733-bf75-fd89416b795a', 'concept'::public.curated_course_node_type, 'Passive and active candidates, alumni, returners, seasonal pools, internships, apprenticeships, and international talent', null, 1),
  ('bbb5214e-655c-4a6d-8f8f-f0e645db2591', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', '9d163ba1-245a-4733-bf75-fd89416b795a', 'concept'::public.curated_course_node_type, 'Source quality, reach, conversion, cost, speed, representation, accessibility, and relationship governance', null, 2),
  ('5d181b1b-cebc-4e2a-8bd2-da0db27ccbeb', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', '7d0abc36-3976-4ff0-bc3d-9a432b607129', 'subtopic'::public.curated_course_node_type, 'Inclusive and lawful recruiting communication', 'Students create accurate, accessible recruitment materials and consistent applicant communication.', 2),
  ('2fc61fdc-2637-4426-acf6-3c468e721063', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', '5d181b1b-cebc-4e2a-8bd2-da0db27ccbeb', 'concept'::public.curated_course_node_type, 'Job-ad content, essential criteria, plain language, accessibility, accommodations, and equal-opportunity statements', null, 0),
  ('47ee64aa-b9b9-4963-9558-5ee754c4f3a7', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', '5d181b1b-cebc-4e2a-8bd2-da0db27ccbeb', 'concept'::public.curated_course_node_type, 'Avoiding exclusionary proxies, inflated requirements, discriminatory targeting, dark patterns, and misleading claims', null, 1),
  ('8fcac66b-274b-4882-8e58-c458ced865f2', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', '5d181b1b-cebc-4e2a-8bd2-da0db27ccbeb', 'concept'::public.curated_course_node_type, 'Applicant tracking, consent, privacy, response standards, candidate experience, and adverse-impact monitoring', null, 2),
  ('1a8a9be4-ca2c-48e9-a90e-5e03b2fde76c', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', null, 'topic'::public.curated_course_node_type, 'Selection, Assessment, Hiring, and Employment Eligibility', 'Selection should predict job performance, protect fairness, and withstand scrutiny. Students learn to combine valid evidence, structured judgment, legal controls, and respectful candidate experience.', 3);
insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('ad8fe17e-4b8d-44cb-b0dd-5447717e75fa', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', '1a8a9be4-ca2c-48e9-a90e-5e03b2fde76c', 'subtopic'::public.curated_course_node_type, 'Selection-system design and validity', 'Students choose methods based on job requirements and evidence, not intuition or convenience.', 0),
  ('c30b7bf6-50c6-4a00-95fe-4f3cc006ab51', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', 'ad8fe17e-4b8d-44cb-b0dd-5447717e75fa', 'concept'::public.curated_course_node_type, 'Reliability, criterion/content/construct validity, utility, standardization, feasibility, and candidate reactions', null, 0),
  ('80848a87-2359-4d12-93cd-4306c3e4ad78', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', 'ad8fe17e-4b8d-44cb-b0dd-5447717e75fa', 'concept'::public.curated_course_node_type, 'Applications, work samples, simulations, situational judgment tests, cognitive/skills tests, and assessment centers', null, 1),
  ('3c4ba75c-acb8-4574-afaf-7c727d59e58e', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', 'ad8fe17e-4b8d-44cb-b0dd-5447717e75fa', 'concept'::public.curated_course_node_type, 'Multiple-hurdle versus compensatory models, cut scores, scoring rubrics, validation evidence, and documentation', null, 2),
  ('b48f596c-fe51-4c36-8196-a4732d6cf89e', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', '1a8a9be4-ca2c-48e9-a90e-5e03b2fde76c', 'subtopic'::public.curated_course_node_type, 'Structured interviewing and reference checks', 'Structured methods improve consistency and make hiring judgments more transparent and coachable.', 1),
  ('4cca7394-0d05-4862-a1f4-3b8b46aea487', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', 'b48f596c-fe51-4c36-8196-a4732d6cf89e', 'concept'::public.curated_course_node_type, 'Behavioral and situational questions, anchored rating scales, interviewer training, panels, note taking, and calibration', null, 0),
  ('74bea1a4-1dfd-44b7-bced-0a3a7cf50e23', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', 'b48f596c-fe51-4c36-8196-a4732d6cf89e', 'concept'::public.curated_course_node_type, 'Job-related probes, prohibited or risky questions, accommodation, language access, bias interrupters, and conflict disclosure', null, 1),
  ('2384b97a-cfce-4453-8fe1-524fb3d25b97', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', 'b48f596c-fe51-4c36-8196-a4732d6cf89e', 'concept'::public.curated_course_node_type, 'Conditional offers, references, background checks, consent, relevance, consistency, privacy, and fair-chance considerations', null, 2),
  ('1c4662a0-34e9-445e-92dc-7a0dbaa6f669', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', '1a8a9be4-ca2c-48e9-a90e-5e03b2fde76c', 'subtopic'::public.curated_course_node_type, 'Decision quality, adverse impact, and onboarding handoff', 'Students audit outcomes across groups and move selected candidates into a compliant, human-centered hiring process.', 2),
  ('b10aac97-21bf-49d9-9963-e876177e1c24', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', '1c4662a0-34e9-445e-92dc-7a0dbaa6f669', 'concept'::public.curated_course_node_type, 'Selection rates, four-fifths heuristic, statistical and practical significance, small samples, and job-related alternatives', null, 0),
  ('824e48fa-3c6f-4946-9697-7db5f8c0a6f2', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', '1c4662a0-34e9-445e-92dc-7a0dbaa6f669', 'concept'::public.curated_course_node_type, 'Offer terms, wage notice, classification, policies, Form I-9, record retention, and jurisdiction-specific requirements', null, 1),
  ('ba8bf0ff-597b-4be2-ad69-dbebfa223950', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', '1c4662a0-34e9-445e-92dc-7a0dbaa6f669', 'concept'::public.curated_course_node_type, 'Preboarding, first-day readiness, payroll/HRIS setup, accommodations, manager ownership, and early feedback', null, 2),
  ('c4b69eeb-3a33-4d3a-93b2-3f74b5114841', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', null, 'topic'::public.curated_course_node_type, 'Onboarding, Learning, Service Culture, and Leadership Development', 'Learning systems turn promises and standards into safe, confident performance. In hospitality, effective development blends technical skill, guest judgment, culture, coaching, practice, feedback, and transfer to the shift.', 4),
  ('934de38b-1b45-4576-b4bb-350f80ce7a91', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', 'c4b69eeb-3a33-4d3a-93b2-3f74b5114841', 'subtopic'::public.curated_course_node_type, 'Onboarding and organizational socialization', 'Students design the first 30–90 days to build clarity, connection, competence, compliance, and confidence.', 0),
  ('d5042121-7601-4750-a940-e0e805bc7145', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', '934de38b-1b45-4576-b4bb-350f80ce7a91', 'concept'::public.curated_course_node_type, 'Preboarding, welcome, role clarity, culture, standards, safety, payroll, benefits, policies, and technology access', null, 0),
  ('df41e196-ca80-46f7-948e-ce3a84af8d93', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', '934de38b-1b45-4576-b4bb-350f80ce7a91', 'concept'::public.curated_course_node_type, 'Manager check-ins, buddy systems, job shadowing, practice, feedback, milestones, and accommodation follow-through', null, 1),
  ('51f8f722-af48-42b2-9cf7-5d1a437d6ab6', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', '934de38b-1b45-4576-b4bb-350f80ce7a91', 'concept'::public.curated_course_node_type, 'New-hire experience measures, time to proficiency, early errors, absence, retention, and corrective redesign', null, 2),
  ('d9c19e65-fd1d-47df-a197-a6e356a94c94', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', 'c4b69eeb-3a33-4d3a-93b2-3f74b5114841', 'subtopic'::public.curated_course_node_type, 'Training needs, design, and facilitation', 'This subtopic uses performance evidence to decide what training can solve and how adults learn best.', 1),
  ('82d6a54d-baac-4f7d-a30b-65584e065980', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', 'd9c19e65-fd1d-47df-a197-a6e356a94c94', 'concept'::public.curated_course_node_type, 'Organization, task, and person analysis; knowledge/skill/motivation/system gaps; priorities and constraints', null, 0),
  ('d8e23a67-fa0d-4b64-81cf-091ad7e1ff11', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', 'd9c19e65-fd1d-47df-a197-a6e356a94c94', 'concept'::public.curated_course_node_type, 'Learning objectives, sequencing, demonstration, deliberate practice, scenarios, simulations, microlearning, and job aids', null, 1),
  ('95dc0b12-7aae-48fa-92c4-d175b437c855', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', 'd9c19e65-fd1d-47df-a197-a6e356a94c94', 'concept'::public.curated_course_node_type, 'Inclusive facilitation, language and literacy, accessibility, psychological safety, feedback, and trainer preparation', null, 2),
  ('84d80800-580b-42c0-9068-cb808e199ef1', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', 'c4b69eeb-3a33-4d3a-93b2-3f74b5114841', 'subtopic'::public.curated_course_node_type, 'Transfer, evaluation, and leadership pipeline', 'Learning has value only when it changes behavior and results in the workplace.', 2),
  ('d08c7fec-2fd0-49b8-bec6-45bc15b3ffab', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', '84d80800-580b-42c0-9068-cb808e199ef1', 'concept'::public.curated_course_node_type, 'Manager reinforcement, opportunity to perform, coaching, communities of practice, nudges, and workflow integration', null, 0),
  ('d9d43042-dd0d-423b-8c29-8e0f598c8a6a', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', '84d80800-580b-42c0-9068-cb808e199ef1', 'concept'::public.curated_course_node_type, 'Reaction, learning, behavior, results, control/comparison, attribution, benefit, cost, and return on expectations', null, 1),
  ('2eb4688c-1370-4189-ab49-aeda23124ec8', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', '84d80800-580b-42c0-9068-cb808e199ef1', 'concept'::public.curated_course_node_type, 'Frontline-supervisor readiness, high-potential risk, mentoring, stretch assignments, leadership standards, and succession pools', null, 2),
  ('31c865fa-eb4b-4d55-82fc-2244db5b0232', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', null, 'topic'::public.curated_course_node_type, 'Motivation, Engagement, Employee Experience, and Voice', 'Hospitality performance depends on sustained human energy under demanding guest-facing conditions. Students examine what creates meaningful effort, trust, belonging, recovery, and constructive voice.', 5),
  ('546438ba-38fe-4c82-963d-9938c2db9730', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', '31c865fa-eb4b-4d55-82fc-2244db5b0232', 'subtopic'::public.curated_course_node_type, 'Motivation and job attitudes', 'Students compare theories and diagnose whether performance barriers arise from value, expectancy, fairness, goals, resources, or work design.', 0),
  ('4be0d6f8-d724-43e9-b882-90bbefe77be5', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', '546438ba-38fe-4c82-963d-9938c2db9730', 'concept'::public.curated_course_node_type, 'Expectancy, equity, self-determination, goal-setting, reinforcement, job characteristics, and psychological contract', null, 0),
  ('8b1b6e12-7e86-46dd-8f37-dcb810f71e7a', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', '546438ba-38fe-4c82-963d-9938c2db9730', 'concept'::public.curated_course_node_type, 'Intrinsic and extrinsic motivation, meaningful work, autonomy, mastery, purpose, recognition, and growth', null, 1),
  ('87158f0a-39f4-4fa9-ad13-29b54ed56c17', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', '546438ba-38fe-4c82-963d-9938c2db9730', 'concept'::public.curated_course_node_type, 'Satisfaction, commitment, burnout, withdrawal, citizenship behavior, service sabotage, and intent to stay', null, 2),
  ('6772a3b4-34de-4857-afec-bf594c1b9780', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', '31c865fa-eb4b-4d55-82fc-2244db5b0232', 'subtopic'::public.curated_course_node_type, 'Employee listening and engagement action', 'Surveys matter only when measures are trustworthy, results are interpreted responsibly, and managers act visibly.', 1),
  ('898f5d09-fc12-45ca-a4ac-0c5033a5d70b', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', '6772a3b4-34de-4857-afec-bf594c1b9780', 'concept'::public.curated_course_node_type, 'Pulse and census surveys, interviews, focus groups, stay interviews, suggestion systems, and digital listening', null, 0),
  ('5129cc5b-3cc8-4181-8389-e13865c6cdaf', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', '6772a3b4-34de-4857-afec-bf594c1b9780', 'concept'::public.curated_course_node_type, 'Constructs, item quality, response bias, anonymity, minimum reporting groups, segmentation, comments, and confidentiality', null, 1),
  ('b967d6cf-746f-46a7-8ef6-1a816b8c98dd', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', '6772a3b4-34de-4857-afec-bf594c1b9780', 'concept'::public.curated_course_node_type, 'Prioritization, local action plans, manager ownership, communication, follow-through, and impact evaluation', null, 2),
  ('e5521de5-5132-45b7-9a67-93f396e23a2c', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', '31c865fa-eb4b-4d55-82fc-2244db5b0232', 'subtopic'::public.curated_course_node_type, 'Voice, psychological safety, and service recovery', 'Employees need safe ways to raise risks, challenge routines, and solve guest problems without fear of retaliation.', 2),
  ('8bc9c7d0-f053-4a9f-9f59-907a43cf8980', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', 'e5521de5-5132-45b7-9a67-93f396e23a2c', 'concept'::public.curated_course_node_type, 'Speaking up, error reporting, dissent, complaints, grievances, whistleblowing, open-door limits, and nonretaliation', null, 0),
  ('1d58066a-6e8b-497a-9e86-da61460d3a08', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', 'e5521de5-5132-45b7-9a67-93f396e23a2c', 'concept'::public.curated_course_node_type, 'Leader inclusiveness, respectful challenge, escalation paths, decision authority, just culture, and learning reviews', null, 1),
  ('b2012b4e-184a-494b-9587-0ab5925d9bab', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', 'e5521de5-5132-45b7-9a67-93f396e23a2c', 'concept'::public.curated_course_node_type, 'Employee empowerment boundaries, guest recovery discretion, resource access, handoffs, and after-action learning', null, 2),
  ('8083cf46-ad4a-48be-8076-75ecbe072e7d', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', null, 'topic'::public.curated_course_node_type, 'Performance Management, Coaching, and Accountability', 'Performance management aligns expectations, ongoing feedback, development, recognition, and fair consequences. The goal is better service and capability—not an annual form completed after the fact.', 6),
  ('80e4a2ff-576d-4fb7-bd8b-c9bdad3c8cd8', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', '8083cf46-ad4a-48be-8076-75ecbe072e7d', 'subtopic'::public.curated_course_node_type, 'Performance architecture and goal setting', 'Students translate strategy and service standards into observable, balanced expectations.', 0);
insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('c0c40584-2b75-4009-9faf-e69b8f232c9b', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', '80e4a2ff-576d-4fb7-bd8b-c9bdad3c8cd8', 'concept'::public.curated_course_node_type, 'Results, behaviors, competencies, values, safety, quality, guest, team, financial, and learning measures', null, 0),
  ('a7096db2-3fb7-4b42-b67e-72abad0ee526', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', '80e4a2ff-576d-4fb7-bd8b-c9bdad3c8cd8', 'concept'::public.curated_course_node_type, 'Specific and challenging goals, controllability, line of sight, weighting, thresholds, stretch, and unintended incentives', null, 1),
  ('4d5ae9c7-bb49-4f2d-9f57-a082711d393f', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', '80e4a2ff-576d-4fb7-bd8b-c9bdad3c8cd8', 'concept'::public.curated_course_node_type, 'Role scorecards, check-ins, probationary reviews, project/shift feedback, and changing-goal governance', null, 2),
  ('7467d9bb-44eb-4ce7-869c-0db6e9d2f9f5', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', '8083cf46-ad4a-48be-8076-75ecbe072e7d', 'subtopic'::public.curated_course_node_type, 'Observation, feedback, and coaching', 'Managers learn to gather evidence, discuss behavior and impact, listen, practice solutions, and support improvement.', 1),
  ('57904e17-4c25-4c93-bd56-55a84cbc0bf8', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', '7467d9bb-44eb-4ce7-869c-0db6e9d2f9f5', 'concept'::public.curated_course_node_type, 'Direct observation, work records, guest feedback, peer input, calibration, recency/halo bias, and documentation', null, 0),
  ('7092a1dd-d753-4daa-b32f-fa9edafd9ea0', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', '7467d9bb-44eb-4ce7-869c-0db6e9d2f9f5', 'concept'::public.curated_course_node_type, 'Situation-behavior-impact, feedforward, active listening, questioning, empathy, cultural humility, and difficult conversations', null, 1),
  ('042728a6-5cf8-408e-926c-67bef9c26ad8', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', '7467d9bb-44eb-4ce7-869c-0db6e9d2f9f5', 'concept'::public.curated_course_node_type, 'Coaching plan, practice, resources, check-backs, reinforcement, recognition, and escalation triggers', null, 2),
  ('85f1819a-c6c8-4e00-8fda-85019e7cd27c', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', '8083cf46-ad4a-48be-8076-75ecbe072e7d', 'subtopic'::public.curated_course_node_type, 'Appraisal, correction, and due process', 'Students distinguish capability, conduct, system, health, and motivation issues before choosing an intervention.', 2),
  ('03e1ce6d-26ec-45ce-8198-17d6da79c193', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', '85f1819a-c6c8-4e00-8fda-85019e7cd27c', 'concept'::public.curated_course_node_type, 'Rating scales, narrative evidence, calibration, forced distribution risks, appeals, and rater accountability', null, 0),
  ('ace94752-f3ef-494f-8b70-d302a1905dee', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', '85f1819a-c6c8-4e00-8fda-85019e7cd27c', 'concept'::public.curated_course_node_type, 'Informal counseling, performance improvement plans, progressive discipline, consistency, mitigating factors, and final decisions', null, 1),
  ('43cc9b00-dbdb-40ca-9b7d-2f2df5c7fee0', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', '85f1819a-c6c8-4e00-8fda-85019e7cd27c', 'concept'::public.curated_course_node_type, 'At-will doctrine limits, contract/union rules, protected activity, accommodation/leave interaction, records, and respectful separation', null, 2),
  ('1f730233-5e8b-4ecf-8e54-7c17ac185d23', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', null, 'topic'::public.curated_course_node_type, 'Compensation, Benefits, Tips, and Scheduling', 'Total rewards communicate what the organization values and shape attraction, fairness, retention, cost, and service. Hospitality adds complex issues of tips, service charges, fluctuating schedules, seasonality, and multi-job labor markets.', 7),
  ('52b81330-383a-4c5a-ab4f-28df2b6adf28', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', '1f730233-5e8b-4ecf-8e54-7c17ac185d23', 'subtopic'::public.curated_course_node_type, 'Compensation strategy and job value', 'Students balance external competitiveness, internal equity, affordability, compliance, and employee understanding.', 0),
  ('82882884-dbce-46a6-be6e-cc9bfd0f79af', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', '52b81330-383a-4c5a-ab4f-28df2b6adf28', 'concept'::public.curated_course_node_type, 'Reward philosophy, market position, base pay, variable pay, premiums, bonuses, commissions, recognition, and noncash rewards', null, 0),
  ('290f66f2-cef9-4793-af34-0c7916388002', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', '52b81330-383a-4c5a-ab4f-28df2b6adf28', 'concept'::public.curated_course_node_type, 'Job evaluation, market pricing, pay grades/bands, ranges, compa-ratio, progression, compression, and geographic differentials', null, 1),
  ('00ba7db3-c798-4754-86ac-d1f85333df24', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', '52b81330-383a-4c5a-ab4f-28df2b6adf28', 'concept'::public.curated_course_node_type, 'Pay transparency, negotiation, discretion, governance, equity audits, communication, and manager training', null, 2),
  ('b747f477-a4ab-4837-a964-26293ce454b0', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', '1f730233-5e8b-4ecf-8e54-7c17ac185d23', 'subtopic'::public.curated_course_node_type, 'Wage-hour, tips, and service-charge controls', 'This subtopic highlights U.S. hospitality pay risks that require current federal, state, local, and collective-agreement review.', 1),
  ('03ac6b0c-2ce5-48b8-849c-2ad8e0d19d3e', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', 'b747f477-a4ab-4837-a964-26293ce454b0', 'concept'::public.curated_course_node_type, 'Employee/independent-contractor and exempt/nonexempt classification; hours worked; overtime; records; deductions', null, 0),
  ('9987f627-3901-4c4e-bafe-e3f9843a1583', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', 'b747f477-a4ab-4837-a964-26293ce454b0', 'concept'::public.curated_course_node_type, 'Tip credit, notice, tip pools, managers/supervisors, dual jobs, tip ownership, service charges, and credit-card fees', null, 1),
  ('50903869-2a53-4f01-a378-eb00b1aa23ff', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', 'b747f477-a4ab-4837-a964-26293ce454b0', 'concept'::public.curated_course_node_type, 'Meal/rest periods, uniforms, training time, travel, on-call time, youth employment, final pay, and local rules', null, 2),
  ('6be83be6-4636-4993-9a10-f9ae0b55af1f', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', '1f730233-5e8b-4ecf-8e54-7c17ac185d23', 'subtopic'::public.curated_course_node_type, 'Benefits, scheduling, and financial well-being', 'Students design rewards and schedules around employee needs, service demand, fairness, and operating resilience.', 2),
  ('92a8f56d-aaad-42c1-9226-fbb1407f289c', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', '6be83be6-4636-4993-9a10-f9ae0b55af1f', 'concept'::public.curated_course_node_type, 'Health, retirement, leave, paid time off, meals, transport, lodging, education, wellness, and voluntary benefits', null, 0),
  ('e19c7cc4-73e2-4b6c-9d17-d70fb3575a20', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', '6be83be6-4636-4993-9a10-f9ae0b55af1f', 'concept'::public.curated_course_node_type, 'Advance notice, availability, shift bidding, self-scheduling, split shifts, clopening, overtime, predictability, and shift swaps', null, 1),
  ('40ca8de8-2f8b-41ae-b8a3-33f0bb3a6d96', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', '6be83be6-4636-4993-9a10-f9ae0b55af1f', 'concept'::public.curated_course_node_type, 'Schedule quality, preference fulfillment, absenteeism, fatigue, turnover, labor cost, service outcomes, and fair-scheduling laws', null, 2),
  ('c90ba22d-0f07-4d1e-afb0-590ed6a5b767', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', null, 'topic'::public.curated_course_node_type, 'Diversity, Equity, Inclusion, Accessibility, and Global Mindset', 'Inclusive hospitality teams serve diverse guests and communities, but business benefits never replace the fundamental duties of fairness and dignity. Students learn to remove barriers across the employee lifecycle.', 8),
  ('fd91192a-b51a-4f2f-9d95-b0c7db16ec54', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', 'c90ba22d-0f07-4d1e-afb0-590ed6a5b767', 'subtopic'::public.curated_course_node_type, 'Systems of inclusion, equity, and belonging', 'Students move beyond representation counts to examine access, treatment, voice, opportunity, advancement, and outcomes.', 0),
  ('b7a16875-cb0d-43b9-9488-480c54779065', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', 'fd91192a-b51a-4f2f-9d95-b0c7db16ec54', 'concept'::public.curated_course_node_type, 'Representation, inclusion, belonging, equity, equality, intersectionality, privilege, structural barriers, and allyship', null, 0),
  ('71d10aea-f757-4ba4-9d1e-37d6ad06c9de', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', 'fd91192a-b51a-4f2f-9d95-b0c7db16ec54', 'concept'::public.curated_course_node_type, 'Lifecycle audits of sourcing, selection, assignment, schedules, pay, development, promotion, discipline, retention, and exit', null, 1),
  ('6feff15b-90a0-4052-9ae6-064c67c0d6d2', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', 'fd91192a-b51a-4f2f-9d95-b0c7db16ec54', 'concept'::public.curated_course_node_type, 'Goals, accountability, employee resource groups, sponsorship, inclusive leadership, backlash risk, and evidence of impact', null, 2),
  ('f9a15477-0d4c-436f-81f4-8d0b0bfeadee', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', 'c90ba22d-0f07-4d1e-afb0-590ed6a5b767', 'subtopic'::public.curated_course_node_type, 'Bias, discrimination, harassment, and retaliation prevention', 'This subtopic combines legal awareness with practical prevention, reporting, response, and culture design.', 1),
  ('83a24a11-b1b8-4db4-8402-f8f68f99c429', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', 'f9a15477-0d4c-436f-81f4-8d0b0bfeadee', 'concept'::public.curated_course_node_type, 'Protected characteristics, disparate treatment, disparate impact, harassment, hostile environment, retaliation, and third-party conduct', null, 0),
  ('f5a2e8ca-54ba-4083-b3e2-43d8253f08b6', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', 'f9a15477-0d4c-436f-81f4-8d0b0bfeadee', 'concept'::public.curated_course_node_type, 'Bias in criteria, referrals, interviews, schedules, guest preferences, appearance rules, language, algorithms, and informal networks', null, 1),
  ('82df4f3d-e2c2-4300-aac1-a76e80174e6d', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', 'f9a15477-0d4c-436f-81f4-8d0b0bfeadee', 'concept'::public.curated_course_node_type, 'Policy, multiple reporting channels, bystander skills, manager response, interim safeguards, investigation, remedies, and monitoring', null, 2),
  ('3ac7b626-2cbf-4d81-8006-f56e5145a5c7', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', 'c90ba22d-0f07-4d1e-afb0-590ed6a5b767', 'subtopic'::public.curated_course_node_type, 'Disability, religion, pregnancy, and other accommodations', 'Students practice the interactive, individualized process needed to identify reasonable work adjustments and protect confidentiality.', 2),
  ('9dad58f2-3b90-4d4a-8bd2-2a75ca008445', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', '3ac7b626-2cbf-4d81-8006-f56e5145a5c7', 'concept'::public.curated_course_node_type, 'Request recognition, essential functions, dialogue, medical-information limits, options, effectiveness, undue hardship, and documentation', null, 0),
  ('a534c13e-d65a-4223-8c43-3d97f7337b5b', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', '3ac7b626-2cbf-4d81-8006-f56e5145a5c7', 'concept'::public.curated_course_node_type, 'Modified schedules, leave, equipment, communication access, task restructuring, reassignment, dress/grooming, prayer, and lactation', null, 1),
  ('12cccd4f-ed6d-4d7d-acbf-df0c1acc5904', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', '3ac7b626-2cbf-4d81-8006-f56e5145a5c7', 'concept'::public.curated_course_node_type, 'Accessibility in recruiting, learning, HR technology, emergency planning, employee events, facilities, and manager communication', null, 2),
  ('88ce3a74-6b50-47f4-aeea-477a3c1da822', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', null, 'topic'::public.curated_course_node_type, 'Employment Law, Employee Relations, Policies, and Investigations', 'U.S. hospitality managers operate amid overlapping federal, state, local, contract, and organizational rules. This section builds issue-spotting, documentation, fair process, and escalation habits—not legal self-confidence beyond one’s competence.', 9),
  ('1529cda5-49c2-4f7e-89e5-42ed29035e1a', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', '88ce3a74-6b50-47f4-aeea-477a3c1da822', 'subtopic'::public.curated_course_node_type, 'Employment-law architecture and issue spotting', 'Students identify the source of a duty, relevant facts, jurisdiction, coverage, deadlines, and the need for qualified advice.', 0),
  ('7751780d-e335-44b6-b457-2ce8620a4c5c', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', '1529cda5-49c2-4f7e-89e5-42ed29035e1a', 'concept'::public.curated_course_node_type, 'At-will employment and exceptions; contracts; handbooks; wage-hour; discrimination; leave; safety; privacy; immigration; labor', null, 0);
insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('9ccc86a3-9127-4c26-afcd-f45bdc0f32b9', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', '1529cda5-49c2-4f7e-89e5-42ed29035e1a', 'concept'::public.curated_course_node_type, 'Federal, state, local, tribal, and international layers; collective agreements; franchise/owner/operator responsibilities', null, 1),
  ('adcced8a-5643-45ee-8ec7-cbe18575594e', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', '1529cda5-49c2-4f7e-89e5-42ed29035e1a', 'concept'::public.curated_course_node_type, 'Employee status, employer coverage, protected status/activity, adverse action, comparator, notice, documentation, preservation, and escalation', null, 2),
  ('7d369afd-f763-48c1-bbfd-1efa0564d807', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', '88ce3a74-6b50-47f4-aeea-477a3c1da822', 'subtopic'::public.curated_course_node_type, 'Policy design and administration', 'A policy should set a clear purpose and process while preserving lawful discretion and consistent implementation.', 1),
  ('07ae26b3-9e7d-4c02-a631-be9ca123b56e', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', '7d369afd-f763-48c1-bbfd-1efa0564d807', 'concept'::public.curated_course_node_type, 'Purpose, scope, definitions, responsibilities, standards, reporting, response, records, nonretaliation, exceptions, and contacts', null, 0),
  ('5d368ead-136f-4642-91d6-ebf37446e139', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', '7d369afd-f763-48c1-bbfd-1efa0564d807', 'concept'::public.curated_course_node_type, 'Plain language, translation, accessibility, acknowledgments, training, version control, distribution, retention, and review cycle', null, 1),
  ('42698f08-eb4d-4c39-92a0-9a957d8fd561', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', '7d369afd-f763-48c1-bbfd-1efa0564d807', 'concept'::public.curated_course_node_type, 'Consistency versus individualized accommodation, manager discretion, past practice, conflicts, waiver risk, and policy audits', null, 2),
  ('188153c4-0b47-4b2f-a3c2-af704fae012b', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', '88ce3a74-6b50-47f4-aeea-477a3c1da822', 'subtopic'::public.curated_course_node_type, 'Complaints, workplace investigations, and corrective action', 'Students learn a neutral, timely, trauma-informed, and well-documented process that protects fairness and evidence.', 2),
  ('7378cf74-8ed2-4fb2-b0dc-dc81e23e2500', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', '188153c4-0b47-4b2f-a3c2-af704fae012b', 'concept'::public.curated_course_node_type, 'Intake, immediate safety, conflicts, scope, investigator independence, interim measures, preservation, and communication plan', null, 0),
  ('75c73aa2-1da9-4533-b8b2-c159213c7916', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', '188153c4-0b47-4b2f-a3c2-af704fae012b', 'concept'::public.curated_course_node_type, 'Interview planning, credibility factors, corroboration, documents/digital evidence, confidentiality limits, standard of proof, and findings', null, 1),
  ('6e62e9b8-ba1e-4084-af87-ffcc4c70a79c', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', '188153c4-0b47-4b2f-a3c2-af704fae012b', 'concept'::public.curated_course_node_type, 'Remedies, discipline, restoration, anti-retaliation monitoring, closure communication, lessons learned, and privilege/counsel boundaries', null, 2),
  ('3c922328-8696-4efa-bc40-7865c0db2c14', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', null, 'topic'::public.curated_course_node_type, 'Labor Relations, Collective Bargaining, and Employee Organizing', 'Labor relations includes employees’ rights to act together whether or not a workplace is unionized. Hospitality managers need lawful, respectful approaches to voice, organizing, bargaining, grievances, and operational continuity.', 10),
  ('6da3fa5c-2d1c-45a3-82c9-de2da5859e44', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', '3c922328-8696-4efa-bc40-7865c0db2c14', 'subtopic'::public.curated_course_node_type, 'Employee rights and organizing context', 'Students recognize protected concerted activity and distinguish lawful manager communication from threats, interrogation, promises, or surveillance.', 0),
  ('f6e02bf1-f82e-44cf-b002-e7eb7c1b865a', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', '6da3fa5c-2d1c-45a3-82c9-de2da5859e44', 'concept'::public.curated_course_node_type, 'National Labor Relations Act coverage, protected concerted activity, union and nonunion settings, supervisors, and exclusions', null, 0),
  ('fdbc3638-38d2-452c-b5d0-c4ccf2331f99', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', '6da3fa5c-2d1c-45a3-82c9-de2da5859e44', 'concept'::public.curated_course_node_type, 'Wages, schedules, safety, tips, discipline, social media, petitions, walkouts, organizing, and third-party activity', null, 1),
  ('df7b821e-940f-43dc-8d41-63db146debe3', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', '6da3fa5c-2d1c-45a3-82c9-de2da5859e44', 'concept'::public.curated_course_node_type, 'Manager conduct, rapid escalation, documentation, neutrality/labor strategy, retaliation risk, and current NLRB guidance', null, 2),
  ('51aa34f2-58eb-4a09-935a-da0defaa33c0', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', '3c922328-8696-4efa-bc40-7865c0db2c14', 'subtopic'::public.curated_course_node_type, 'Representation and collective bargaining', 'This subtopic explains how a union becomes the representative and how parties negotiate terms and conditions in good faith.', 1),
  ('7273a8a2-3ead-4fd5-9bc3-875b10b98a6a', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', '51aa34f2-58eb-4a09-935a-da0defaa33c0', 'concept'::public.curated_course_node_type, 'Campaigns, petitions, bargaining units, elections/recognition, objections, certification, and first-contract challenges', null, 0),
  ('cf091a57-4399-4c49-a8de-c14552e8d301', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', '51aa34f2-58eb-4a09-935a-da0defaa33c0', 'concept'::public.curated_course_node_type, 'Mandatory, permissive, and prohibited subjects; proposals, costing, caucuses, package bargaining, impasse, mediation, and ratification', null, 1),
  ('0402393a-1cf0-4a2f-9f85-ea59dbefcab1', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', '51aa34f2-58eb-4a09-935a-da0defaa33c0', 'concept'::public.curated_course_node_type, 'Management rights, union security, dues, seniority, scheduling, subcontracting, technology, safety, discipline, and duration', null, 2),
  ('0edce943-ca50-48dc-bb1b-bdf74f2cc6ab', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', '3c922328-8696-4efa-bc40-7865c0db2c14', 'subtopic'::public.curated_course_node_type, 'Contract administration, grievances, and conflict', 'Students apply agreement language, past practice, evidence, and just-cause principles to daily decisions.', 2),
  ('c6ff6f92-7316-4b81-a2f4-96f1962656ec', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', '0edce943-ca50-48dc-bb1b-bdf74f2cc6ab', 'concept'::public.curated_course_node_type, 'Grievance steps, timelines, standing, information requests, steward rights, representation during interviews, and settlements', null, 0),
  ('09c36972-8490-4333-b869-8611b804cdef', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', '0edce943-ca50-48dc-bb1b-bdf74f2cc6ab', 'concept'::public.curated_course_node_type, 'Just cause, notice, reasonable rule, investigation, proof, equal treatment, progressive discipline, and penalty', null, 1),
  ('632e0421-93f0-400c-ab89-f1498690d05c', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', '0edce943-ca50-48dc-bb1b-bdf74f2cc6ab', 'concept'::public.curated_course_node_type, 'Arbitration, strikes, lockouts, picketing, contingency planning, guest/service continuity, safety, and relationship rebuilding', null, 2),
  ('8040e01c-a39d-4ca8-8f42-706e9ebe0e4a', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', null, 'topic'::public.curated_course_node_type, 'Workplace Safety, Health, Well-Being, and Crisis Readiness', 'Safe work is a core employment condition and service prerequisite. Hospitality hazards include slips, burns, cuts, chemicals, ergonomics, heat, fatigue, violence, infectious disease, and psychological strain.', 11),
  ('ec25c560-a9ef-449c-8e82-de9f5ba5106e', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', '8040e01c-a39d-4ca8-8f42-706e9ebe0e4a', 'subtopic'::public.curated_course_node_type, 'Safety management and hazard control', 'Students use worker participation and the hierarchy of controls to prevent harm before relying on individual behavior.', 0),
  ('0e4b2d39-c3d3-44f1-b253-d442d2c3a8a7', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', 'ec25c560-a9ef-449c-8e82-de9f5ba5106e', 'concept'::public.curated_course_node_type, 'Leadership commitment, worker participation, hazard identification, incident/near-miss reporting, inspections, and risk assessment', null, 0),
  ('4a79f32e-043b-421b-9f09-2832a90789ec', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', 'ec25c560-a9ef-449c-8e82-de9f5ba5106e', 'concept'::public.curated_course_node_type, 'Elimination, substitution, engineering controls, administrative controls, personal protective equipment, and residual risk', null, 1),
  ('8d996f80-b932-4e8f-b284-fbe432fc9384', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', 'ec25c560-a9ef-449c-8e82-de9f5ba5106e', 'concept'::public.curated_course_node_type, 'Housekeeping ergonomics, kitchen hazards, slips/falls, chemicals, heat, equipment, young workers, contractors, and emergency plans', null, 2),
  ('aae68bf4-d46d-442b-9644-79a54ddba850', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', '8040e01c-a39d-4ca8-8f42-706e9ebe0e4a', 'subtopic'::public.curated_course_node_type, 'Incident response, accommodation, and return to work', 'Managers must respond quickly, preserve care and evidence, meet reporting duties, and support safe recovery.', 1),
  ('7b3fd9f1-f5c4-4017-8883-dab6e1722bb3', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', 'aae68bf4-d46d-442b-9644-79a54ddba850', 'concept'::public.curated_course_node_type, 'First aid/emergency response, scene control, notification, records, workers’ compensation, regulator reporting, and privacy', null, 0),
  ('a946ed9a-e88e-445b-9edc-78db56f8073a', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', 'aae68bf4-d46d-442b-9644-79a54ddba850', 'concept'::public.curated_course_node_type, 'Root-cause learning, human factors, corrective actions, owner/due dates, verification, trend review, and nonretaliation', null, 1),
  ('9d80038f-7cbc-4ed1-aea7-6478c7551d09', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', 'aae68bf4-d46d-442b-9644-79a54ddba850', 'concept'::public.curated_course_node_type, 'Functional abilities, temporary modifications, interactive accommodation, transitional work, case coordination, and relapse prevention', null, 2),
  ('3264c068-c6d3-462f-a348-9aebdf8abd8b', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', '8040e01c-a39d-4ca8-8f42-706e9ebe0e4a', 'subtopic'::public.curated_course_node_type, 'Well-being, fatigue, violence, and crisis readiness', 'Students treat psychosocial risk and crisis capacity as operating-system issues, not resilience slogans.', 2),
  ('b8fba0b9-4441-427e-ac27-fae693d67584', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', '3264c068-c6d3-462f-a348-9aebdf8abd8b', 'concept'::public.curated_course_node_type, 'Workload, staffing, schedule quality, emotional labor, incivility, harassment, burnout, substance concerns, and employee assistance', null, 0),
  ('945a67b2-cdfa-4eec-a6a9-879ef356f214', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', '3264c068-c6d3-462f-a348-9aebdf8abd8b', 'concept'::public.curated_course_node_type, 'Workplace-violence assessment, late-night/cash/public-contact risks, de-escalation, duress, security, reporting, and post-event support', null, 1),
  ('f0f3c143-3202-4ddd-97c3-80dd1f925bed', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', '3264c068-c6d3-462f-a348-9aebdf8abd8b', 'concept'::public.curated_course_node_type, 'Severe weather, fire, health events, active threats, evacuation/shelter, communication, staffing continuity, drills, and after-action review', null, 2),
  ('ada56fcd-83e2-47d0-bf7c-5a91ce38ed71', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', null, 'topic'::public.curated_course_node_type, 'Retention, Career Development, Succession, and Workforce Resilience', 'Retention should focus on regrettable, preventable loss and on creating credible opportunities—not on keeping every employee indefinitely. Students connect mobility, manager quality, work design, rewards, and workforce resilience.', 12),
  ('86f12675-f520-42af-a6cc-59d345769a08', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', 'ada56fcd-83e2-47d0-bf7c-5a91ce38ed71', 'subtopic'::public.curated_course_node_type, 'Turnover diagnosis and retention strategy', 'Students distinguish voluntary/involuntary, regrettable/nonregrettable, avoidable/unavoidable, and early/tenured turnover.', 0),
  ('3d7881c1-7451-4db9-bcac-2e594c5607c0', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', '86f12675-f520-42af-a6cc-59d345769a08', 'concept'::public.curated_course_node_type, 'Turnover, stability, survival curves, cohort analysis, exit and stay data, absence, internal mobility, and vacancy cost', null, 0),
  ('6505dc8d-e504-43b5-8ce3-540ab2735da3', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', '86f12675-f520-42af-a6cc-59d345769a08', 'concept'::public.curated_course_node_type, 'Selection, onboarding, manager, pay, schedule, workload, fairness, safety, belonging, growth, commute, and life-stage drivers', null, 1);
insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('47fd9d7d-312f-4b45-a2e5-600223561561', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', '86f12675-f520-42af-a6cc-59d345769a08', 'concept'::public.curated_course_node_type, 'Segmented interventions, ethical retention, pilots, leading indicators, cost/benefit, controls, and unintended lock-in', null, 2),
  ('c95fe457-dcf7-4573-84fe-47e1eae75a99', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', 'ada56fcd-83e2-47d0-bf7c-5a91ce38ed71', 'subtopic'::public.curated_course_node_type, 'Career architecture and internal mobility', 'Visible pathways help employees understand how skills and performance can lead to opportunity across departments, properties, brands, and functions.', 1),
  ('dee195f1-9aba-42a6-9831-9ea993df147e', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', 'c95fe457-dcf7-4573-84fe-47e1eae75a99', 'concept'::public.curated_course_node_type, 'Career ladders and lattices, job families, levels, competencies, credentials, skill profiles, and transparent criteria', null, 0),
  ('ee911787-f6fa-4741-aaad-3de957d3525c', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', 'c95fe457-dcf7-4573-84fe-47e1eae75a99', 'concept'::public.curated_course_node_type, 'Internal job markets, transfers, promotions, cross-training, stretch work, internships, mentoring, sponsorship, and tuition support', null, 1),
  ('cab473d1-f515-4f53-a5e0-4c8e2ec3d172', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', 'c95fe457-dcf7-4573-84fe-47e1eae75a99', 'concept'::public.curated_course_node_type, 'Opportunity equity, manager talent hoarding, readiness, relocation, pay changes, replacement plans, and employee choice', null, 2),
  ('51a0482f-36a8-4b73-bcdd-327cb93343fc', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', 'ada56fcd-83e2-47d0-bf7c-5a91ce38ed71', 'subtopic'::public.curated_course_node_type, 'Succession, critical roles, and workforce resilience', 'Students prepare for leadership and skill continuity without treating succession charts as predictions.', 2),
  ('84fa91a8-f5dc-4fae-9466-3550c16c46ee', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', '51a0482f-36a8-4b73-bcdd-327cb93343fc', 'concept'::public.curated_course_node_type, 'Critical roles and capabilities, vacancy risk, bench strength, readiness horizon, emergency successors, and single points of failure', null, 0),
  ('ebd89dfc-ded5-4665-b32b-fd5d236db993', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', '51a0482f-36a8-4b73-bcdd-327cb93343fc', 'concept'::public.curated_course_node_type, 'Talent reviews, evidence, calibration, potential versus performance, bias controls, development actions, and confidentiality', null, 1),
  ('b65f97e8-75aa-46fa-8161-11bd8cd5f729', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', '51a0482f-36a8-4b73-bcdd-327cb93343fc', 'concept'::public.curated_course_node_type, 'Cross-training, knowledge capture, communities of practice, contingent capacity, scenario plans, and plan effectiveness', null, 2),
  ('3357dbdd-5efc-4206-9181-8fa5fd5f778e', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', null, 'topic'::public.curated_course_node_type, 'HR Technology, People Analytics, Responsible AI, and the Integrated HR Policy Case', 'Digital systems can improve access, consistency, insight, and employee service while also creating privacy, bias, security, surveillance, and vendor risks. The course culminates in an evidence-based people strategy and policy case.', 13),
  ('de61cf12-ee60-4f5a-b233-42606c91954b', 'c4d5e6f7-8a9b-4c19-8d18-2e3f4a5b6c09', '3357dbdd-5efc-4206-9181-8fa5fd5f778e', 'subtopic'::public.curated_course_node_type, 'HR systems, employee service, and data governance', 'Students map the HR technology ecosystem and define trustworthy controls across the data lifecycle.', 0),
